export const PARCOURS_LITTORAL_EAU: ParcoursFormation = {
    id: 'littoral-eau', titre: 'Le littoral sous l’influence des marées', duree: "7 min",
    objectif: "Relier marée, courant, vagues et déplacements du sable à ce que le groupe vit sur son lieu de pratique.",
    actionsTerrain: [{ id: 'lire-indice' }, { id: 'comparer' }, { id: 'situer' }],
    ressources: [wiki.littoral, wiki.marees, wiki.coefficients], sources: [shom],
    fiches: [
        f("Même plage, autre espace", "La marée fait monter et descendre le niveau de la mer, principalement sous l’effet de la Lune et du Soleil. En Manche, deux pleines mers et deux basses mers se succèdent généralement en un peu plus de 24 heures. Pour le groupe, cela se voit dans le lieu : cale recouverte, plage découverte, banc qui disparaît. Les possibilités d’usage changent avec ce niveau.", "Au départ, faites repérer une zone du rivage : « La retrouverons-nous visible au retour ? ». Reprenez cette hypothèse depuis une position adaptée.", "La marée transforme le lieu que nous utilisons.", "Partir d’un changement vécu pendant la sortie pour faire comprendre que le littoral n’est pas un espace disponible de la même façon à toute heure.", "Regardez la zone où nous avons préparé les bateaux. Au retour, l’eau pourra la recouvrir. Nous naviguons dans un lieu qui change, et les autres usages de la plage changent avec lui."),
        f("Ce qui monte et ce qui nous emporte", "Le courant déplace l’eau ; la marée en change le niveau. Les deux peuvent être liés sans évoluer au même rythme : la pleine mer ne garantit pas un arrêt du courant. Le vent et d’autres phénomènes peuvent aussi déplacer l’eau. Une écume qui dérive rend ce mouvement visible, mais seulement à cet endroit et en surface.", "Faites décrire le niveau sur un support fixé au rivage et la dérive d’une écume : « Qu’est-ce qui monte ? Qu’est-ce qui se déplace ? ». Ne jetez rien à l’eau.", "Niveau et déplacement de l’eau sont deux observations différentes.", "Dissocier deux expériences du groupe — changement de hauteur et dérive — avec des mots concrets, plutôt qu’une définition isolée du courant.", "L’eau gagne de la hauteur sur la cale, et elle peut aussi nous déporter. Ce sont deux mouvements différents. Regardons ce qui nous permet de voir chacun d’eux ici."),
        f("Des vagues venues d’ailleurs", "Les vagues agitent la surface et sont souvent produites par le vent. Une houle peut arriver d’une zone éloignée où le vent a soufflé : peu de vent local ne signifie donc pas absence de vagues. Le groupe peut ainsi comprendre que son lieu de pratique est relié à des phénomènes plus lointains, sans rechercher l’origine exacte de chaque vague.", "Pendant une pause adaptée, comparez vent ressenti et vagues visibles : « Le vent d’ici suffit-il à expliquer ce que l’on voit ? ».", "Le vent d’ici n’explique pas toujours les vagues d’ici.", "Utiliser un écart entre vent ressenti et vagues pour ouvrir la perception du site au-delà de ce qui est visible depuis le bateau.", "Nous sentons peu de vent, mais ces vagues arrivent quand même. Le vent qui les a formées a pu souffler ailleurs. Notre plage est reliée à ce qui se passe plus loin en mer."),
        f("Une plage mobile, pas un décor", "Vagues et courants peuvent enlever du sable dans une zone et le déposer ailleurs. Le rivage est mobile. Mais une plage moins large n’a pas forcément perdu du sable : elle peut être davantage recouverte ou vue sous un autre angle. Une comparaison rapide ne suffit pas à expliquer une évolution durable. Distinguez la différence visible et sa cause possible.", "Comparez le rivage depuis le même point au départ et au retour : « Qu’est-ce qui a changé ? Est-ce une preuve de déplacement du sable ? ». Notez la marée.", "Un changement visible ne donne pas à lui seul son explication.", "Faire discuter une différence du rivage sans transformer une impression en diagnostic d’érosion. Séparer description et explication dans le langage employé.", "La plage paraît moins large. Avant de dire qu’elle a perdu du sable, regardons la marée et notre point de vue. Ce que nous voyons a changé ; il reste à comprendre pourquoi."),
        f("Un chiffre qui a besoin d’un lieu", "Le marnage est la différence de hauteur entre pleine et basse mer. Un coefficient plus élevé correspond généralement à un marnage plus grand, sans donner directement la hauteur à la cale ni la profondeur sous le bateau. Pour parler du site à un moment donné, utilisez le lieu, l’heure et la hauteur prévue ; gardez vos références habituelles pour préparer la navigation.", "Sur une prévision locale, faites distinguer heure, hauteur et coefficient : « Quelle information nous parle de la cale à l’heure du retour ? ».", "Le coefficient est un repère d’amplitude, pas une hauteur locale.", "Remplacer le jargon du bulletin par la question concrète du groupe : ce que l’eau fera à cet accès au moment de la séance.", "Le coefficient nous parle de l’importance de la marée. Pour savoir ce qui nous attend à cette cale au retour, il faut aussi regarder l’heure et la hauteur prévues ici."),
        f("Une hypothèse au départ, un retour à l’arrivée", "Un changement vécu pendant la séance peut donner du sens à une notion d’environnement. Choisissez une seule différence accessible : niveau sur la cale, dérive ou rivage recouvert. Faites décrire, expliquez le lien avec le phénomène, puis reprenez l’activité. Votre observation habituelle de moniteur devient une occasion courte de transmettre.", "Au départ : « Que retrouverons-nous au retour ? ». À une pause prévue, reprenez le repère et faites formuler une explication au groupe.", "Une observation vécue peut devenir une idée comprise et partagée.", "Organiser un fil d’échange bref entre deux moments de la séance. Le groupe vérifie une hypothèse sur le lieu à partir de sa propre expérience.", "Au départ, nous pensions que cette zone serait recouverte. Qu’observons-nous maintenant ? Quel phénomène explique la différence ? Gardons cette observation pour lire le site à la prochaine sortie."),
    ], questions: [
        q(0, "Une zone de plage utilisée au départ est recouverte au retour. Vous voulez faire comprendre ses usages changeants. Quel angle choisir ?", ["Présenter les forces qui produisent la marée pour expliquer tout le cycle.","Comparer ce que cette zone permettait au départ et ce qui y est possible maintenant.","Faire retenir les horaires du lendemain pour préparer une autre navigation."], 1, "Comparer les usages d’un même espace rend concret le lien entre variation du niveau et fonctionnement du littoral. L’explication du cycle peut répondre à une autre curiosité, et les horaires servent à préparer une sortie. Ici, l’objectif est de faire regarder autrement le lieu déjà vécu par le groupe."),
        q(1, "Le groupe a ressenti une dérive pendant la navigation. Comment prolonger cette expérience vers une compréhension du milieu ?", ["Définir le courant et demander au groupe de redonner la définition.","Présenter les prévisions de courant de toute la zone pour compléter le briefing.","Faire relier la dérive vécue à un déplacement d’eau observable à cet endroit."], 2, "Un lien entre sensation vécue et indice visible donne prise à l’explication. Le groupe peut comprendre ce que fait l’eau plutôt que mémoriser un terme. Prévisions et vocabulaire ont leur utilité, mais leur présentation seule ne construit pas ce lien entre expérience et observation."),
        q(2, "Peu de vent est ressenti, mais une houle arrive. Vous voulez montrer que le site est relié à des phénomènes plus éloignés. Quelle formulation choisir ?", ["Les prévisions de vagues nous aident à préparer cette séance.","Le vent d’ici ne raconte pas tout : ces vagues peuvent venir d’une zone où le vent a soufflé.","Regardons la taille des vagues pour choisir les réglages adaptés."], 1, "La formulation s’appuie sur un contraste visible pour ouvrir le regard au-delà du site. Les deux autres propositions concernent la préparation ou la conduite de la navigation. Elles sont utiles en voile, mais ne développent pas ici le lien environnemental recherché."),
        q(3, "Le groupe conclut à une érosion à partir de deux photos de plage. Quelle relance aide à construire une explication fiable ?", ["Qu’est-ce qui diffère dans les images, et avons-nous le même point de vue et le même niveau d’eau ?","Quels événements depuis la première photo pourraient expliquer le sable perdu ?","Quelle photographie rend le changement le plus facile à présenter au groupe ?"], 0, "La première relance distingue constat, conditions de comparaison et explication. Chercher directement une cause de perte de sable valide trop tôt l’hypothèse du groupe. Choisir une image parlante peut aider une présentation, mais n’établit pas ce qui a réellement changé."),
        q(4, "Vous avez déjà préparé la séance avec les prévisions de marée. Comment rendre le bulletin utile à un échange sur le lieu avec le groupe ?", ["Faire apprendre les termes du bulletin avant d’observer le rivage.","Relier l’heure et la hauteur attendues à une zone du site que le groupe retrouve au retour.","Présenter toute la semaine de coefficients pour montrer la diversité des situations."], 1, "Relier les informations au lieu et à un moment vécu traduit le bulletin en paysage observable. Le vocabulaire et la comparaison des coefficients peuvent compléter un autre échange. Ils ne sont pas nécessaires pour construire cette entrée concrète et courte."),

        q(5, "Au départ, vous faites repérer une zone de plage. Au retour, elle est recouverte. Quel échange donne du sens environnemental à cette expérience ?", ["Présenter les horaires de marée du lendemain avant de reprendre la séance.","Faire décrire la différence et la relier au niveau d’eau qui a changé.","Faire mémoriser le coefficient pour expliquer tous les changements du rivage."], 1, "Le groupe dispose d’une observation vécue : on peut relier le changement du paysage au niveau de l’eau, puis reprendre la séance. Les horaires peuvent servir à préparer une autre sortie, mais n’expliquent pas cette comparaison à eux seuls. Le coefficient ne résume ni la hauteur instantanée ni tous les mouvements du rivage."),
    ],
};
export const PARCOURS_LAISSE_DE_MER: ParcoursFormation = {
    id: 'laisse-de-mer', titre: 'Réduire l’impact humain', duree: "7 min",
    objectif: "Faire comprendre l’utilité des dépôts naturels et choisir des gestes de collecte adaptés au lieu et à la séance.",
    actionsTerrain: [{ id: 'distinguer' }, { id: 'observer' }, { id: 'geste-adapte' }], ressources: [wiki.gestes, wiki.impact],
    fiches: [
        f("Faire raconter un dépôt", "La laisse de mer rassemble des éléments déposés par les vagues et les marées, en lignes ou en amas selon les conditions. Elle ne garantit pas la limite de la prochaine marée. Le groupe peut partir d’un constat : la mer transporte des matières puis les laisse sur la plage. Leur origine et leur rôle se discutent avant de décider de les enlever.", "À terre, depuis un accès autorisé : « Qu’est-ce qui a pu amener ces éléments ici ? ». Distinguez le dépôt d’une prévision de hauteur d’eau.", "Un dépôt du rivage mérite d’être compris avant d’être retiré.", "Changer le regard initial sur un amas avant toute décision de nettoyage. L’origine et le rôle ouvrent l’échange, plutôt que l’aspect visuel.", "Cette ligne rassemble ce que l’eau a déposé. Avant de décider de tout enlever, demandons-nous d’où viennent ces éléments et à quoi ils peuvent encore servir ici."),
        f("Justifier un tri plutôt que réciter une consigne", "Algues, bois, coquilles et restes d’animaux peuvent former des dépôts naturels. Plastiques et emballages peuvent s’y mêler sans donner la même origine ou le même rôle à tous les éléments. Décrivez la matière et l’origine probable. En cas de doute sur un élément, laissez-le en place et prévoyez de vérifier sa nature. Un amas n’est pas un déchet uniquement parce qu’il paraît désordonné ou sent fort.", "Faites décrire trois éléments sans les manipuler : « Lequel est un déchet identifiable ? Sur quoi vous appuyez-vous ? ». Écartez les éléments douteux de la manipulation.", "La nature des éléments oriente le geste.", "Faire expliciter le critère de choix du groupe. Une origine incertaine reste une question à vérifier, sans pousser à manipuler les éléments.", "Qu’est-ce qui vous fait dire que cet élément est un déchet ? Décrivons sa matière et son origine probable. Être mélangé à un emballage ne transforme pas tout le dépôt en déchets."),
        f("Ce qui paraît abandonné peut encore servir", "Les matières échouées peuvent abriter et nourrir de petits organismes, eux-mêmes recherchés par des oiseaux. La laisse relie ainsi les dépôts de la mer à la vie du haut de plage. Une algue hors de l’eau garde donc une utilité pour le milieu. L’observation se fait depuis le bord, sans retourner les amas pour voir leurs habitants.", "Si un indice est visible à distance : « Qu’est-ce que ce dépôt peut apporter au vivant ? ». Sinon, expliquez le lien sans exiger une rencontre ni modifier l’abri.", "Une matière échouée peut encore nourrir et abriter du vivant.", "Employer un lien alimentaire et un rôle d’abri pour expliquer la préservation des dépôts naturels, sans devoir montrer ou nommer leurs habitants.", "Ces matières sorties de l’eau peuvent encore nourrir et abriter de petits organismes. D’autres animaux s’en nourrissent ensuite. Ce dépôt n’a pas cessé d’avoir un rôle parce qu’il est échoué."),
        f("Évaluer le geste par son effet", "Les dépôts naturels peuvent retenir du sable et apporter de la matière à la végétation en se décomposant. Les retirer change donc plus que l’apparence de la plage. Une collecte se juge par ce qui a été enlevé et conservé, pas seulement au volume du sac ou à l’aspect final. Cela distingue une intention de nettoyer et l’effet réel du geste.", "Depuis l’accès prévu : « Une plage sans aucun dépôt serait-elle forcément mieux préservée ? ». Reliez dépôts, sable et végétation visibles.", "L’effet du nettoyage dépend de ce qui est retiré.", "Déplacer le bilan d’une collecte de la quantité vers ce qui a été conservé ou retiré. Faire comprendre la différence entre propreté visuelle et préservation.", "Nous avons retiré des déchets, mais laissé des matières utiles au haut de plage. Que garde le milieu grâce à ce choix ? Le volume du sac ne raconte pas à lui seul l’effet de notre collecte."),
        f("Trois gestes, trois raisons", "Préservez les éléments naturels. Une collecte de déchets humains suit les consignes locales, les accès autorisés et les conditions de manipulation. Un objet coupant, suspect ou dangereux se signale au responsable. Un déchet ne rend pas une zone fermée accessible. Expliquez pourquoi on peut laisser, collecter ou signaler selon l’élément et le lieu.", "Avant une collecte éventuelle, faites justifier l’une des trois suites : laisser, collecter selon les consignes, signaler. N’exposez pas le groupe aux objets dangereux.", "Le geste tient compte de l’élément et du site.", "Donner des éléments de langage pour expliquer pourquoi on laisse, collecte ou signale. Le choix tient compte de l’objet et du site.", "Cet élément naturel reste sur place. Ce déchet peut être collecté selon nos consignes. Cet autre objet se signale au responsable : sa présence ne justifie pas d’entrer dans une zone fermée ni de le manipuler."),
        f("Comprendre avant de passer à l’action", "On peut parler d’impact humain sans organiser une collecte. Un dépôt naturel et un déchet visibles suffisent pour faire discuter leur rôle et un geste adapté. Si une collecte est prévue, reprenez cette distinction dans les consignes et le bilan. L’objectif est de comprendre l’effet des choix, pas de remplir le plus grand sac.", "Pendant une pause à terre : « Pour prendre soin de cette plage, que faudrait-il laisser et pourquoi ? ». Retenez une raison liée au milieu.", "Réfléchir au rôle des éléments donne du sens au geste.", "Garder une courte occasion de transmission même sans collecte organisée. Le raisonnement sur le rôle des éléments est l’objectif de l’échange.", "Pour prendre soin de cette plage, que faudrait-il laisser, et pourquoi ? Choisissons un exemple que nous pouvons expliquer avant de reprendre notre activité."),
    ], questions: [
        q(0, 'Après la marée, une ligne d’algues, de bois et de coquilles borde la plage. Quelle idée en faire retenir ?', ['Elle marque la limite que la prochaine marée atteindra.', 'Elle rassemble des éléments déposés par le passage de l’eau.', 'Elle rassemble les éléments transportés par le vent de terre.'], 1, 'Cette ligne correspond à des dépôts laissés par les vagues et les marées. Elle renseigne sur un passage de l’eau, sans garantir la limite de la prochaine marée. Le bois ou les coquilles ne suffisent pas à attribuer le dépôt au vent.'),
        q(1, 'Dans une zone où la collecte est autorisée, algues et emballages sont mêlés. Quelle consigne donner au groupe ?', ['Retirer l’amas mêlé pour éviter de laisser du plastique.', 'Retirer les algues sèches avec les emballages visibles.', 'Retirer les déchets accessibles, laisser les dépôts naturels.'], 2, 'On distingue l’origine et la nature des éléments plutôt que de traiter tout l’amas comme un déchet. Les algues sèches restent des dépôts naturels utiles au milieu. La collecte suit aussi les consignes du site et les conditions de manipulation.'),
        q(2, 'Une stagiaire demande pourquoi on laisse des algues échouées qui ne sont plus dans l’eau. Quel lien expliquer ?', ['Elles nourrissent et abritent du vivant sur le haut de plage.', 'Leur utilité dépend surtout de leur retour dans la mer.', 'Leur utilité tient surtout à l’ombre qu’elles font au sable.'], 0, 'Même déposées sur la plage, les matières naturelles peuvent nourrir de petits organismes et leur offrir un abri ; des oiseaux peuvent ensuite s’en nourrir. Leur utilité ne dépend donc pas d’un retour à l’eau et ne se résume pas à l’ombre produite.'),
        q(3, 'Un nettoyage a rendu le haut de plage très net. Sur quoi appuyer votre échange avec le groupe ?', ['Sur la quantité retirée pour apprécier l’effet du nettoyage.', 'Sur ce qui a été retiré pour distinguer déchets et dépôts utiles.', 'Sur l’aspect final pour apprécier la préservation de la plage.'], 1, 'L’aspect net et le volume ramassé ne disent pas, à eux seuls, si le geste a préservé le milieu. Retirer les déchets humains et enlever les dépôts naturels ont des effets différents. Les dépôts peuvent aussi retenir du sable et participer à la vie du haut de plage.'),
        q(4, 'Un déchet coupant est visible derrière le balisage d’une zone sensible. Quelle suite donner à cette découverte ?', ['Demander à un adulte de le retirer en empruntant le même passage.', 'Prévoir une collecte ciblée avec le groupe en fin de séance.', 'Le signaler au responsable en précisant son emplacement.'], 2, 'Le signalement permet de transmettre le problème sans franchir la zone ni exposer le groupe à l’objet. La présence d’un déchet n’autorise pas une collecte dans un secteur fermé. Le responsable peut organiser une intervention adaptée.'),

        q(5, "Après une collecte préparée, quel bilan aide le groupe à comprendre son effet sur la plage ?", ["Comparer le volume des sacs pour désigner la collecte la plus utile.","Évaluer l’aspect du sable pour vérifier que le nettoyage est réussi.","Distinguer les déchets retirés et les éléments naturels laissés pour leur rôle."], 2, "Le bilan porte sur l’effet des choix : déchets humains retirés dans les conditions prévues, matières naturelles conservées pour le milieu. Volume et aspect peuvent décrire la collecte, mais ne suffisent pas à montrer ce qu’elle a préservé. Le groupe peut ainsi réutiliser le raisonnement lors d’une autre séance."),
    ],
};
export const PARCOURS_FORMATION: ParcoursFormation[] = [
    PARCOURS_LITTORAL_EAU,
    {
        id: 'vent-meteo', titre: 'La situation géographique du lieu', duree: "6 min",
        objectif: "Faire lire le lieu de pratique dans son ensemble : sa place sur la côte, la forme du rivage, les milieux voisins et les liens entre terres, mer et activités humaines.",
        actionsTerrain: [], ressources: [wiki.littoral, wiki.reperes, wiki.usages],
        sources: [{ titre: 'Les milieux marins et littoraux — OFB', href: 'https://ofb.gouv.fr/les-milieux-marins-et-littoraux' }, { titre: 'Le fonctionnement des dunes — ONF', href: 'https://www.onf.fr/onf/%2B/2ce1::dunes-littorales-fonctionnement-menaces.html' }],
        fiches: [
            f("Notre plage dans un littoral plus vaste", "Vous connaissez déjà votre zone de navigation. Une carte ou une vue aérienne permet de dépasser le seul plan d’eau de la séance : prolongement de la côte, baie, pointe ou débouché d’un cours d’eau, selon le site. Choisissez un lien qui aide à comprendre le paysage visible. Il suffit de situer le lieu dans cet ensemble ; une liste de noms ne raconte pas encore son fonctionnement.", "Avant le départ, montrez la zone de séance sur une carte puis élargissez le cadre : « Qu’est-ce qui prolonge notre plage de chaque côté ? ». Retrouvez un de ces éléments depuis l’eau.", "Notre lieu de pratique fait partie d’un ensemble littoral.", "Utiliser vos repères de navigation pour donner au groupe une vue d’ensemble du lieu, au-delà de la plage de départ.", "Nous partons de cette plage. Sur la carte, regardez comment elle se prolonge et ce qu’il y a juste à côté. Depuis les bateaux, nous allons retrouver un de ces liens dans le paysage."),
            f("La forme du rivage raconte le lieu", "Une côte ouverte, une baie ou une pointe ne présentent pas la même configuration. Vous utilisez déjà cette géographie pour organiser la séance. Elle peut aussi aider le groupe à comprendre des contrastes du paysage : secteur exposé, recoin plus abrité, plage ou bord rocheux. La forme du rivage est une piste à croiser avec les conditions du jour ; elle ne suffit pas à expliquer chaque différence d’agitation ou de végétation.", "À une pause prévue, comparez deux secteurs visibles : « Qu’est-ce que la forme de la côte pourrait changer entre ces deux endroits ? ». Appuyez l’explication sur un contraste réel du jour.", "La forme de la côte aide à comprendre les différences entre secteurs.", "Prolonger votre lecture nautique d’un secteur par une question sur ce que sa configuration change pour le milieu.", "D’ici, on voit que le rivage change de forme. Ce secteur est plus ouvert, celui-là se trouve derrière une avancée. Regardons ce qui diffère aujourd’hui : la forme de la côte nous donne une piste, à croiser avec les conditions."),
            f("Des milieux voisins, un même paysage", "La plage, la dune, les rochers ou les zones humides voisines composent le littoral, selon les lieux. Ils ne sont pas de simples décors indépendants : sur une côte sableuse, le sable de la plage peut alimenter la dune, où la végétation contribue à le retenir. Faire comprendre une relation entre deux espaces suffit. Les autres parcours permettent d’approfondir le vivant ou les dunes ; ici, on donne une lecture d’ensemble.", "Depuis un accès existant, faites suivre du regard le paysage de l’eau vers les terres : « Où change-t-on de milieu ? Qu’est-ce qui relie deux de ces espaces ? ». Choisissez un seul lien que vous pouvez expliquer.", "Lire le littoral, c’est aussi voir les liens entre ses milieux.", "Faire regarder la succession des espaces depuis votre trajet habituel, puis donner une relation simple plutôt qu’un inventaire.", "Depuis l’eau, regardons la plage puis la dune. Ce sont deux milieux différents, mais ils sont liés : le sable de la plage peut rejoindre la dune et y être retenu par la végétation. Notre plage appartient à ce paysage d’ensemble."),
            f("La mer est aussi reliée aux terres", "Les cours d’eau et le ruissellement relient les terres au littoral. À l’embouchure d’un cours d’eau, l’eau douce rejoint la mer ; elle peut transporter des sédiments et des matières venant de plus loin à terre. Une carte aide à raconter ce lien, même si l’amont n’est pas visible. Une eau colorée ne permet pas, à elle seule, de conclure à une pollution : il faut distinguer le trajet de l’eau et un diagnostic sur sa qualité.", "Si un cours d’eau débouche dans votre secteur, retrouvez son trajet sur une carte : « Avant d’arriver ici, par quels lieux cette eau est-elle passée ? ». Sinon, gardez cette entrée pour un site où le lien est identifiable.", "Ce qui arrive sur le littoral peut venir de plus loin à terre.", "Élargir le regard vers l’amont grâce à un lien géographique concret, sans transformer une observation visuelle en diagnostic de qualité de l’eau.", "Cette eau rejoint la mer ici, mais son trajet a commencé plus loin dans les terres. La carte nous permet de remonter ce chemin. Notre lieu de navigation est aussi relié à des espaces que nous ne voyons pas depuis le bateau."),
            f("Un paysage aussi habité", "Une cale, un port, des habitations ou des installations de production situent la pratique sportive dans un territoire habité. Leur emplacement donne une entrée pour raconter les liens entre géographie et activités : accès à l’eau, proximité des terres, espace abrité ou zone découverte, selon le site. Faites observer une relation vérifiable. L’histoire d’un aménagement ou son effet précis sur le rivage demande une source locale ; sa présence seule ne les explique pas.", "Choisissez un aménagement que le groupe utilise ou aperçoit : « Qu’est-ce que cet emplacement permet de faire ? ». Reliez un élément du paysage à une activité, puis reprenez la séance.", "La situation du lieu contribue aussi à organiser les activités humaines.", "Partir d’un aménagement familier pour faire comprendre comment les activités prennent place dans le paysage, sans raconter toute l’histoire du site.", "Cette cale relie les terres à notre zone de navigation. Ailleurs sur le rivage, d’autres aménagements permettent d’autres activités. Qu’est-ce que leur emplacement nous apprend sur la façon dont ce lieu est utilisé ?"),
        ], questions: [
            q(0, "Vous voulez présenter le lieu avant le départ, au-delà du seul plan d’eau de la séance. Comment utiliser une carte en une minute ?", ["Présenter les principaux amers et faire mémoriser leurs noms avant de partir.", "Situer la plage, montrer son lien avec un élément côtier voisin et proposer de le retrouver depuis l’eau.", "Décrire tout le secteur côtier pour que le groupe dispose d’un panorama complet."], 1, "Une relation géographique à retrouver sur le terrain donne du sens à la carte sans allonger la préparation. Les amers servent déjà à la pratique nautique ; ici, on s’appuie sur eux pour ouvrir la lecture du paysage. Le panorama complet disperse cet échange bref."),
            q(1, "Le groupe remarque un contraste entre un secteur ouvert et un recoin derrière une pointe. Quelle relance sert la lecture du lieu ?", ["Conclure que la pointe explique le contraste, puis passer aux réglages adaptés.", "Reprendre les directions du vent pour vérifier les connaissances nautiques du groupe.", "Faire décrire la différence, puis discuter ce que la forme de la côte et les conditions du jour peuvent expliquer."], 2, "Le contraste devient une occasion de lire la configuration du site. On propose une explication à partir du lieu et des conditions observées, sans attribuer automatiquement toute différence à la pointe. Les réglages restent utiles à la navigation, mais ne portent pas à eux seuls cet échange environnemental."),
            q(2, "Depuis l’eau, plage et dune sont visibles. Vous disposez d’une courte pause pour faire comprendre le paysage d’ensemble. Quel angle choisir ?", ["Montrer les deux espaces et expliquer un lien entre eux, comme le sable qui peut passer de la plage à la dune.", "Présenter les principales espèces de chaque espace pour caractériser leurs différences.", "Décrire surtout le vent du jour et ses effets sur la conduite des bateaux."], 0, "Une relation entre deux espaces rend la géographie du paysage concrète. Elle donne une idée à retenir sans demander un inventaire. Le vent peut intervenir dans ce lien, mais l’entrée reste la relation plage-dune, plutôt qu’un nouvel échange consacré à la navigation."),
            q(3, "Près d’une embouchure, le groupe demande pourquoi l’eau paraît différente. Vous souhaitez ouvrir un échange sur les liens entre terres et mer. Quelle réponse choisir ?", ["Associer la couleur à une pollution venant des terres pour rendre le lien immédiatement parlant.", "Montrer sur la carte le trajet du cours d’eau et préciser que la couleur seule ne permet pas de juger la qualité de l’eau.", "Expliquer uniquement les conditions de navigation près de l’embouchure pour rester dans une situation connue."], 1, "Le trajet du cours d’eau donne une relation géographique solide à raconter. On peut parler de ce qui vient des terres sans déduire une pollution de la couleur. Les conditions de navigation relèvent de votre préparation sportive ; cette question offre aussi une ouverture vers l’environnement."),
            q(4, "Au retour près de la cale, vous voulez prolonger la séance par une lecture du territoire habité. Quelle question est la plus adaptée ?", ["Quels réglages avons-nous utilisés pour rejoindre cet accès ?", "À quelle date cet aménagement a-t-il été construit et qui l’a financé ?", "Qu’est-ce que cet emplacement permet de faire, et quelles autres activités voit-on prendre place sur le rivage ?"], 2, "La question relie un emplacement et des activités visibles : le groupe peut comprendre le paysage à partir de l’accès qu’il vient d’utiliser. Le bilan des réglages poursuit un autre objectif. L’histoire de l’aménagement peut enrichir une prochaine séance si elle est documentée, mais n’est pas nécessaire pour cette entrée."),
        ],
    },
    {
        id: 'milieux-vivants', titre: 'La biodiversité locale en fonction des saisons', duree: "6 min", objectif: "Relier les formes de vie observables aux conditions du lieu et de la saison pour en parler pendant une séance sportive.", actionsTerrain: [], ressources: [wiki.littoral, wiki.algues, wiki.plantes, wiki.vivant],
        fiches: [
            f("Changer de secteur, changer de conditions", "Plage, estran, dune et pré salé offrent des conditions différentes : eau, sel, support et exposition. La végétation d’un sable sec et celle d’un sol recouvert d’eau salée ne sont donc pas interchangeables. Pour expliquer la diversité du littoral, partez de ces différences visibles. Elles donnent une clé utile sans demander de reconnaître toutes les espèces.", "Depuis un chemin, comparez deux zones : « Où voit-on de l’eau ? Le sol est-il le même ? ». Reliez une différence de végétation au milieu.", "Les conditions du lieu aident à comprendre le vivant.", "Faire construire une explication de la diversité à partir de contrastes visibles, avant de chercher des noms d’espèces.", "Entre ce sable sec et cette zone régulièrement recouverte, les conditions ne sont pas les mêmes. Regardez la végétation : de quoi dispose-t-elle ici, et à quoi est-elle exposée ?"),
            f("La marée change aussi la vie à terre", "L’estran est la zone couverte et découverte par la marée. Ses parties basses restent généralement immergées plus longtemps ; une mare conserve de l’eau lorsque les rochers voisins sont à l’air. Les organismes ne rencontrent donc pas tous les mêmes conditions. La position dans le lieu aide à comprendre ce que l’on observe, même sans connaître son nom.", "Depuis le bord d’une mare accessible, demandez : « Qu’est-ce qui reste dans cette mare quand la roche voisine est à l’air ? ». Observez sans déplacer d’organismes ni entrer dans la mare.", "La position sur l’estran change les conditions de vie.", "Partir de la marée, déjà prise en compte pour la navigation, pour parler de ce qu’elle change pour les organismes du rivage : être sous l’eau ou à l’air.", "La mer est descendue, mais cette mare a gardé de l’eau. Les organismes qui sont dedans ne vivent pas la même situation que ceux des rochers découverts. La marée change leurs conditions aussi."),
            f("Parler du support avant de chercher le nom", "Une algue peut être attachée à un rocher et recouverte par la marée ; une plante de pré salé, comme la salicorne, est enracinée dans un sol salé. Le sel ne fait pas de toute végétation une algue. Faites regarder le support et la relation à l’eau : ce sont des clés pour parler juste, sans apprendre une classification.", "Comparez une algue sur son support et une plante dans le sol : « À quoi sont-elles attachées ? Quand l’eau arrive-t-elle ici ? ». Laissez-les en place.", "Support et relation à l’eau permettent une distinction simple.", "Répondre à une confusion sur la végétation en faisant décrire sa relation au lieu. L’identification devient un complément, pas le préalable de l’échange.", "Avant de chercher son nom, regardons où cela pousse : sur un rocher recouvert par la mer, ou dans un sol salé ? Cette différence nous apprend déjà quelque chose sur sa façon de vivre."),
            f("Pourquoi les rencontres changent", "La saison change la végétation et les usages du site par les animaux : alimentation, reproduction, hivernage ou halte pendant un déplacement. La marée et le comportement changent aussi ce qui est visible. Une ressource sur le début d’été ne promet donc pas les mêmes rencontres toute l’année. Ne rien voir lors d’un passage ne prouve pas une disparition.", "Si les rencontres diffèrent d’une sortie à l’autre, précisez date, marée et activité : « Le moment change-t-il ce que nous voyons ? ». Vérifiez les repères saisonniers locaux.", "Saison et marée donnent du contexte à l’observation.", "Donner du sens aux différences entre les rencontres faites lors de deux séances en reliant moment, saison et besoins du vivant, sans promettre une espèce à voir.", "Nous ne rencontrons pas toujours le même vivant. Ce lieu peut servir à se nourrir, se reposer ou faire une halte selon le moment. Qu’est-ce qui diffère de notre dernière sortie ?"),
            f("Un lieu qui répond à un besoin", "Choisissez un contraste visible pendant une pause : eau conservée dans une mare, végétation du sable sec ou zone découverte utilisée par des oiseaux. Faites décrire la différence, puis reliez-la à une condition de vie ou un besoin. Une idée suffit : le vivant n’occupe pas le littoral au hasard. Les noms peuvent être vérifiés plus tard.", "À une pause prévue : « Qu’est-ce que cet endroit offre que le secteur voisin n’offre pas ? ». Retenez un lien entre milieu et vivant.", "Une différence de milieu donne une entrée pour en parler.", "Faire dégager une seule relation entre milieu et vivant pendant une pause. Éviter que l’échange devienne une liste de rencontres à identifier.", "Qu’est-ce que cet endroit offre que le secteur voisin n’offre pas ? Regardons ce que ce lieu offre, puis cherchons à quel besoin cela peut répondre."),
        ], questions: [
            q(0, 'Le groupe ne voit pas les mêmes plantes dans la dune et dans le pré salé voisin. Quelle piste explorer ?', ['Le degré de maturité de deux végétations du même milieu.', 'La fréquentation humaine comme explication de ce contraste.', 'Les différences d’eau, de sel et de sol entre les deux milieux.'], 2, 'Ces milieux offrent des conditions de vie différentes : présence d’eau, salinité, sol et exposition. C’est la première piste pour comprendre leur végétation. L’âge des plantes ou la fréquentation peuvent poser d’autres questions, mais ne remplacent pas cette comparaison du milieu.'),
            q(1, 'À marée basse, une mare garde de l’eau alors que les rochers voisins sont découverts. Quelle idée faire observer ?', ['Les conditions diffèrent entre la mare et les zones à l’air.', 'La mare représente les conditions de tout l’estran à marée basse.', 'Les rochers à l’air ont quitté la zone soumise aux marées.'], 0, 'La mare conserve un milieu aquatique tandis que les supports voisins sont exposés à l’air. Ces différences existent au sein du même estran. Les rochers découverts restent dans la zone que la marée peut couvrir à nouveau.'),
            q(2, 'Une stagiaire appelle « algues » les plantes enracinées du pré salé. Quelle distinction lui proposer ?', ['Leur taille permet de distinguer les plantes des algues.', 'Leur milieu et leur mode de vie permettent de les distinguer.', 'La présence de sel permet de les classer parmi les algues.'], 1, 'Une plante enracinée dans un sol salé, comme la salicorne, ne se confond pas avec une algue vivant dans l’eau ou sur un support de l’estran. La taille ou la présence de sel ne suffisent pas à les distinguer. L’objectif est de relier le vivant à son milieu, sans réciter des noms.'),
            q(3, 'En octobre, un secteur semble moins animé qu’en juin. Quelle formulation respecte les limites de votre observation ?', ['Le secteur accueille moins de vivant depuis cet été.', 'Les animaux observés en juin ont terminé leur migration.', 'Le moment et les conditions changent ce qui est visible.'], 2, 'La saison, la marée et les comportements influencent ce que l’on voit. Deux passages ne suffisent pas à conclure à une baisse du vivant ni à expliquer le déplacement de chaque animal. Vous pouvez décrire la différence et rechercher les informations saisonnières du site.'),

            q(4, "Pendant une pause, le groupe compare une mare et une roche découverte. Quel échange construit un lien entre milieu et vivant ?", ["Faire chercher le nom de chaque organisme pour classer les deux secteurs.","Compter les organismes visibles pour dire quel secteur est le plus riche.","Faire décrire la présence d’eau et les conditions offertes dans chaque secteur."], 2, "Le contraste d’eau disponible donne une entrée concrète pour comprendre les conditions de vie. Des noms peuvent compléter cette découverte plus tard. Un comptage rapide entre deux secteurs différents ne suffit pas à mesurer leur richesse et ne remplace pas le lien entre milieu et vivant."),
        ],
    },
    {
        id: 'littoral-partage', titre: 'Les activités humaines au fil des jours', duree: "6 min", objectif: "Faire comprendre comment notre séance s’inscrit dans un littoral utilisé pour travailler, circuler et vivre.", actionsTerrain: [], ressources: [wiki.usages, wiki.elevage, wiki.impact],
        fiches: [
            f("Notre terrain de sport sert aussi à d’autres", "Une plage peut servir à accéder à l’eau, circuler, travailler et nourrir des oiseaux. Ces fonctions ne sont pas toutes visibles au même instant. Repérez les besoins avant d’installer le groupe : garder un passage, accéder aux installations ou laisser un secteur au repos. Un espace disponible pour nous ne perd pas pour autant ses autres usages.", "Faites repérer un usage humain et un usage du vivant : « De quoi chacun a-t-il besoin ici ? ». Reliez-les à l’emplacement du groupe.", "Notre séance se déroule dans un espace partagé.", "Donner du sens au partage à partir des besoins observables sur le site, plutôt que commencer par une liste d’interdictions.", "Pour nous, c’est un accès à l’eau. Pour d’autres, c’est un passage, un lieu de travail ou un endroit où se nourrir. Comment organiser notre séance pour respecter ces besoins ?"),
            f("Raconter une activité liée à la mer", "Les tables ostréicoles servent à l’élevage des huîtres ; les bouchots sont des pieux utilisés pour les moules. Ce sont des installations de production avec des accès de travail, pas des équipements d’animation. Leur rôle montre une activité humaine liée à la mer. Pour ses particularités et ses horaires, utilisez les informations locales plutôt que de supposer.", "Depuis une zone autorisée : « À quoi servent ces installations ? Quel accès faut-il laisser libre ? ». Expliquez sans toucher ni entrer dans la zone de travail.", "Reconnaître une installation permet de comprendre un usage du littoral.", "Utiliser une installation visible comme porte d’entrée sur le lien entre milieu marin et activité humaine. La fonction suffit, sans détailler toute la production.", "Ces installations servent à élever des coquillages. Les professionnels ont besoin d’y accéder et d’y travailler. Notre passage prend place dans ce même espace : regardons l’accès qu’il faut garder libre."),
            f("Le partage a aussi une horloge", "La marée change les espaces accessibles et les créneaux d’activité. Un secteur de travail découvert peut être recouvert au retour. Le partage ne se règle donc pas seulement par une carte des zones, mais aussi par le moment. Ce rythme relie nos choix de séance aux activités des autres et au milieu mobile dont elles dépendent.", "Comparez un secteur au départ et au retour : « Qui peut l’utiliser maintenant ? Qu’est-ce qui a changé ? ». Appuyez-vous sur les usages réellement observés.", "Partager le lieu demande de tenir compte de ses rythmes.", "Faire expliquer pourquoi les usages se croisent différemment selon le moment de la marée, à partir du site que le groupe vient de parcourir.", "Cet espace était disponible au départ et il est maintenant recouvert. Comme notre navigation, certains travaux et passages dépendent de ce rythme. Partager le lieu, c’est aussi tenir compte du moment."),
            f("Expliquer le besoin derrière la consigne", "Un passage professionnel, un accès balisé ou un secteur sensible répond à un besoin local. Reliez votre choix au rôle du lieu : laisser circuler, éviter le piétinement ou préserver une zone de repos. Cette explication donne du sens à la consigne. Consultez les indications du site et de la base ; une habitude sur une autre plage ne se transpose pas automatiquement.", "Avant la préparation : « Où installer nos bateaux pour garder cet accès libre ? ». Faites observer le passage et expliquez l’emplacement retenu.", "Voir le besoin préservé aide à comprendre la consigne.", "Présenter votre choix d’organisation comme une réponse à un besoin local. Le groupe comprend la raison du geste et peut la réutiliser ailleurs.", "Nous préparons le matériel ici pour laisser ce passage libre. La question n’est pas seulement où nous avons de la place, mais ce que notre installation permet encore aux autres de faire."),
            f("Faire parler un choix de séance", "Un choix d’organisation peut accueillir une notion d’environnement : où poser le matériel, quel accès prendre ou quel secteur contourner. Faites observer le besoin concerné et expliquez comment notre séance en tient compte. Un exemple réel suffit pour montrer que notre pratique s’inscrit parmi d’autres usages et dans un milieu vivant.", "Pendant la préparation : « Pourquoi avons-nous choisi cet endroit plutôt que ce passage ? ». Retenez le lien avec l’accès à préserver, puis reprenez l’installation.", "Nos choix de séance peuvent faire comprendre notre place sur le littoral.", "Profiter d’un choix déjà nécessaire — emplacement ou trajet — pour lancer un échange bref sur notre place dans le littoral.", "Pourquoi avons-nous choisi cet emplacement plutôt que celui-là ? Quel usage gardons-nous possible ? Une fois ce besoin repéré, notre choix de séance devient plus facile à comprendre."),
        ], questions: [
            q(0, 'Avant une séance, vous repérez un passage professionnel et des oiseaux au repos. Quel échange lancer sur le partage du lieu ?', ['Repérer les autres activités humaines présentes autour du groupe.', 'Relier notre usage aux besoins humains et animaux du lieu.', 'Comparer les horaires des différents groupes sportifs du site.'], 1, 'Le partage concerne les activités humaines et les besoins du vivant : travailler, circuler, se nourrir ou se reposer. Les horaires des sportifs et les autres activités humaines comptent, mais ne suffisent pas à expliquer la présence des oiseaux et leurs besoins.'),
            q(1, 'À marée basse, le groupe voit des rangées de pieux portant des moules. Que peut-on expliquer sur cet espace ?', ['Il sert à l’élevage des moules et possède des accès de travail.', 'Il sert à retenir les moules sauvages déplacées par la marée.', 'Il sert à protéger les bancs de sable contre les courants.'], 0, 'Ce sont des bouchots, des supports utilisés pour l’élevage des moules. Les repérer permet de comprendre un usage professionnel et ses accès. Leur aspect ne doit pas faire confondre une installation de production avec un dispositif de protection du rivage.'),
            q(2, 'Un secteur utilisé par des professionnels ce matin est recouvert à votre retour. Quel lien faire avec les activités du littoral ?', ['Les usages dépendent surtout du nombre de personnes sur place.', 'Les activités à terre suivent les mêmes créneaux chaque jour.', 'La marée modifie les espaces et les créneaux utilisables.'], 2, 'La montée et la descente de l’eau changent les accès et les moments possibles pour certains usages. Comprendre ce rythme aide à partager le lieu. La fréquentation intervient aussi, mais elle n’explique pas pourquoi ce secteur est désormais recouvert.'),
            q(3, 'Pour faire respecter une consigne locale de passage, quelle explication relie le mieux la règle au lieu ?', ['Préciser ce que cet accès permet de préserver ou de desservir.', 'Présenter cette règle comme une habitude de fonctionnement du club.', 'Expliquer que le même type de passage convient sur chaque plage.'], 0, 'Relier la consigne à un besoin concret — accès professionnel, végétation ou secteur sensible — lui donne du sens. Une habitude du club ne dit pas pourquoi elle existe, et les consignes dépendent du site. Le groupe comprend ce que son geste préserve ici.'),

            q(4, "Vous déplacez la préparation du matériel pour garder un passage professionnel libre. Comment faire de ce choix une notion partagée ?", ["Faire observer le passage et expliquer le besoin auquel notre choix répond.","Présenter le déplacement comme une préférence d’organisation du moniteur.","Faire retenir cet emplacement comme celui à utiliser sur toutes les plages."], 0, "La situation permet de relier un choix concret au partage du lieu. La consigne devient compréhensible au-delà d’une préférence du moniteur. L’emplacement reste adapté à ce site et à ses usages ; il ne constitue pas une règle identique pour toutes les plages."),
        ],
    },
    {
        id: 'lire-eau', titre: 'Lire les mouvements de l’eau', duree: "6 min", objectif: "Faire distinguer au groupe niveau, déplacement et traces de l’eau à partir d’observations simples pendant la séance.", actionsTerrain: [], ressources: [wiki.mer, wiki.marees, wiki.coefficients], sources: [shom],
        fiches: [
            f("Donner au groupe un moyen de vérifier", "L’avancée d’une vague ne prouve pas que la marée monte. Choisissez un support fixé au rivage et comparez le niveau à deux moments depuis un point adapté. Regardez plusieurs instants pour distinguer les oscillations des vagues et une évolution du niveau. Le groupe peut ainsi vérifier une hypothèse avec le même repère au lieu de confronter seulement des impressions.", "Repérez le contact de l’eau sur un poteau ou un rocher, puis revenez-y à une pause : « Qu’est-ce qui nous montre une variation de niveau ? ».", "Même support fixe, deux moments : on peut comparer le niveau.", "Transformer une impression de montée ou de descente en observation partagée. La compétence du moniteur sert à choisir l’indice, pas à réciter la définition de la marée.", "Vous avez l’impression que le niveau monte. Gardons ce repère sur le poteau et regardons-le au retour : qu’est-ce qui pourrait confirmer notre idée ?"),
            f("Un indice, avec ses limites", "Une écume déjà présente rend visible un mouvement de surface par rapport à un repère. Suivez-la plusieurs instants plutôt qu’une seule vague. Ce constat reste local : il ne mesure pas le courant partout ou au fond. Vent et vagues peuvent aussi intervenir. Décrivez le mouvement observé avant d’en faire une explication de toute la zone.", "Faites suivre une écume sans rien jeter : « Dans quel sens se déplace-t-elle ici ? Peut-on conclure la même chose partout ? ».", "Un indice de surface montre un déplacement local.", "Faire décrire un déplacement avant d’étendre son explication au site entier. Montrer comment on distingue ce que l’on constate de ce que l’on suppose.", "Cette écume se déplace devant notre repère. Cela nous parle de la surface à cet endroit. Avons-nous assez d’indices pour dire que l’eau se déplace de la même façon partout ?"),
            f("Deux constats qui ne se contredisent pas", "La pleine mer décrit un maximum de niveau, pas un arrêt garanti du déplacement de l’eau. L’étale du niveau et celle du courant peuvent être décalées selon le site. Deux constats sont donc compatibles : la hauteur varie peu, mais l’écume dérive. Observez-les séparément ; les prévisions de niveau et de courant ne répondent pas à la même question.", "Si les indices sont visibles : « L’eau change-t-elle de hauteur ? Se déplace-t-elle ? ». Faites formuler les deux constats avant de les expliquer.", "Un niveau presque stable n’implique pas un courant nul.", "Débloquer une confusion du groupe en comparant deux indices indépendants. L’explication s’appuie sur la scène, pas sur le vocabulaire technique à mémoriser.", "Le niveau change très peu, mais l’écume continue de dériver. Ces deux observations peuvent aller ensemble : changer de hauteur et se déplacer ne sont pas la même chose."),
            f("Ce que la plage raconte du passage de l’eau", "Une ligne de dépôts ou une zone humide peut signaler un passage de l’eau. Elle ne garantit pas la limite de la prochaine marée : hauteur prévue, vent et vagues peuvent modifier ce qui sera atteint. Faire distinguer trace passée et prévision aide le groupe à comprendre pourquoi observer et préparer la suite sont deux démarches complémentaires.", "À terre, observez une ligne depuis l’accès prévu : « Que peut-elle nous dire ? Que ne garantit-elle pas ? ». Utilisez vos prévisions locales pour organiser la suite.", "Une trace renseigne sur un passage, pas sur une limite future certaine.", "Employer une trace comme récit du lieu, en indiquant clairement la limite entre ce qu’elle montre et ce qu’elle permet de prévoir.", "Cette ligne nous raconte un passage de l’eau. Elle ne nous promet pas où l’eau arrivera la prochaine fois. Quelles informations faudrait-il ajouter pour parler de la suite ?"),
            f("Une question plutôt qu’une invitation vague", "« Regardez la mer » mêle plusieurs phénomènes. Choisissez une question : niveau, dérive ou trace du rivage. Donnez un repère commun et un court temps de regard adapté à la séance. Faites dire ce qui a été vu, puis ce que cela permet de comprendre. Une seule observation menée jusqu’à une idée à retenir suffit.", "Pendant une pause : « L’eau touche-t-elle le même endroit sur ce poteau ? ». Distinguez le constat et son explication, puis reprenez l’activité.", "Un phénomène et un repère donnent une consigne d’observation claire.", "Préparer une consigne précise qui rend l’observation possible en quelques instants. Choisir un seul phénomène et un repère accessible au groupe.", "Regardons le contact de l’eau avec ce poteau. Est-il au même endroit qu’au départ ? Décrivons la différence avant d’essayer de l’expliquer."),
        ], questions: [
            q(0, "Le groupe affirme que la mer monte après avoir vu une vague avancer. Quelle relance lui donne un moyen de vérifier ?", ["Quelle vague vous a paru la plus grande pendant la séance ?","Quel coefficient était annoncé pour cette sortie ?","Quel repère fixe pouvons-nous comparer maintenant et au retour ?"], 2, "La relance installe une observation partagée correspondant à l’hypothèse du groupe. Une vague isolée et le coefficient ne montrent pas directement la variation de niveau pendant ce créneau. Le moniteur choisit le repère ; le groupe construit le constat."),
            q(1, "Une écume dérive devant le groupe. Quelle formulation fait travailler à la fois observation et limites de l’interprétation ?", ["Nous voyons un déplacement de surface ici ; quels autres indices faudrait-il pour parler de toute la zone ?","Cette écume illustre le courant prévu ; retenons sa direction pour le reste de la séance.","Cette écume donne un aperçu du courant ; commençons par apprendre les termes employés dans l’atlas."], 0, "La première formulation donne sa juste portée au constat et ouvre une question. Elle n’étend pas un indice local à la suite de la séance ou à tout le site. Le vocabulaire documentaire peut être utile au moniteur sans devoir précéder cet échange avec le groupe."),
            q(2, "À pleine mer, le groupe voit encore de l’écume dériver et demande une explication. Quelle entrée permet un échange bref ?", ["Présenter le tableau de courants du site avant de reprendre l’observation.","Faire décrire séparément ce que montre le niveau et ce que montre la dérive.","Demander au groupe de retenir l’horaire où il a rencontré cette situation."], 1, "Deux descriptions concrètes permettent de montrer que variation de hauteur et déplacement ne sont pas la même observation. Les données locales peuvent étayer la réponse du moniteur. La mémorisation d’un horaire ou la présentation préalable d’un tableau ne rendent pas à elles seules ce contraste compréhensible."),
            q(3, "Une ligne de dépôts intrigue le groupe. Quel angle relie cet indice à une lecture du littoral ?", ["La ligne est un repère pratique : utilisons-la pour organiser le rangement.","La ligne permet de montrer une hauteur : présentons les valeurs du bulletin.","La ligne raconte un passage de l’eau : demandons ce qu’elle montre et ce qu’elle ne prédit pas."], 2, "L’angle choisi fait parler une trace du milieu et ses limites. Une utilisation pratique et une lecture du bulletin peuvent avoir leur place dans la séance. Ici, le groupe apprend à distinguer une histoire visible du rivage et une prévision de la suite."),

            q(4, "Vous voulez faire observer la montée de la marée pendant la séance. Quelle consigne donne une base de comparaison utile ?", ["Suivez l’écume la plus visible jusqu’à ce qu’elle quitte la zone.","Regardez la vague qui avance le plus loin sur la plage.","Repérez le niveau sur ce poteau, puis comparons-le au retour."], 2, "Le même support fixé au rivage permet de comparer le niveau à deux moments. L’écume renseigne plutôt sur un déplacement de surface. L’avancée d’une vague isolée ne suffit pas à montrer une évolution de marée. La consigne doit correspondre au phénomène que vous voulez faire observer."),
        ],
    },
    {
        id: 'reperes', titre: 'Prendre ses repères', duree: "6 min", objectif: "Utiliser des repères partagés pour faire décrire et comparer un littoral qui change pendant la séance.", actionsTerrain: [], ressources: [wiki.reperes, wiki.littoral, wiki.marees],
        fiches: [
            f("Un repère pour partager le même regard", "Un amer est un repère terrestre reconnaissable depuis la mer : phare, bâtiment ou relief. Il doit être visible et assez distinct pour éviter une confusion. Faire préciser un détail permet au groupe de regarder le même endroit. Ce repère peut ensuite aider à retrouver un secteur du littoral et à décrire ce qui change autour de lui.", "Au briefing ou à une pause : « Quel détail distingue ce repère de son voisin ? ». Retrouvez-le sur une carte adaptée et vérifiez que chacun situe le même secteur.", "Un repère partagé permet de parler du même lieu.", "Réutiliser vos repères de navigation pour guider le regard du groupe vers un secteur du littoral. L’apport porte sur la transmission, pas sur l’apprentissage des amers.", "Retrouvons notre repère. Regardez maintenant le rivage autour de lui : quelle partie est découverte, et qu’est-ce que l’eau a recouvert ? Nous parlons bien tous du même secteur."),
            f("Choisir le repère qui raconte le changement", "Le support dépend de ce que l’on compare. Un bâtiment fixe aide à situer un secteur ; un bateau mobile ne donne pas la même référence. Une bouée peut bouger autour de son mouillage et suivre le niveau de l’eau. Pour comparer une hauteur, choisissez un support fixé au rivage : un repère de navigation ne convient pas à toute observation.", "Proposez une bouée et un poteau visibles : « Lequel pourrait montrer que le niveau a changé ? Pourquoi ? ». Reliez le choix à la question.", "Le repère doit convenir à ce que l’on veut comparer.", "Faire comprendre au groupe que l’indice doit correspondre à la question posée. Votre choix professionnel devient un outil pour regarder le milieu.", "Pour comparer la hauteur d’eau, ce support fixé au rivage nous aide. La bouée monte et descend avec l’eau : elle ne nous raconte pas le changement de la même manière. Quel indice répond à notre question ?"),
            f("Situer un paysage dans le temps", "Banc de sable, plage et accès changent d’aspect avec le niveau d’eau. Décrire un secteur demande donc de situer l’endroit et le moment. Prenez la prévision du jour pour le lieu de référence adapté au site ; l’horaire d’une autre sortie ne suffit pas. Un repère terrestre peut rester reconnaissable pendant que le rivage autour de lui évolue.", "Faites repérer un banc : « Est-il visible maintenant ? Le sera-t-il au retour ? ». Situez cette question dans votre prévision locale.", "Position et moment permettent de décrire un lieu qui évolue.", "Associer un lieu déjà reconnu par le groupe au moment de sa découverte. Cela prépare une comparaison du paysage au retour.", "Nous savons où se trouve ce banc. Mais pour dire ce qu’on y voit, il faut aussi préciser quand on regarde. Retrouverons-nous le même paysage à l’heure du retour ?"),
            f("Distinguer changement du lieu et changement de regard", "Un autre angle ou cadrage peut modifier la largeur apparente d’une plage sans démontrer une évolution du milieu. Pour comparer, gardez un point accessible et un repère fixe ; notez date, heure et marée. Cette démarche rend l’observation plus compréhensible. Elle ne donne pas, avec deux photos seulement, un diagnostic de l’évolution du littoral.", "Au départ et au retour, utilisez le même accès : « Qu’est-ce qui change autour du repère resté en place ? ». Gardez le contexte avec les photos.", "Repère stable et contexte connu rendent la comparaison utile.", "Questionner une comparaison trop rapide en faisant expliciter point de vue et contexte. Donner au groupe une méthode simple pour discuter une évolution.", "Cette photo paraît différente. Avons-nous regardé du même endroit et au même niveau de marée ? Commençons par comparer notre manière de regarder avant de conclure que le lieu a changé."),
            f("Un fil entre départ et retour", "Un repère utilisé dans la séance sportive peut aussi faire regarder l’environnement : secteur de navigation, plage ou accès de retour. Faites décrire le rivage autour de lui, puis reprenez une question au retour. Le groupe observe ainsi un lieu qui évolue sans ajouter un exercice complet de navigation ou de photographie.", "Au retour : « Qu’est-ce qu’on voit différemment autour de notre repère ? ». Reliez une différence aux conditions de la sortie et reprenez l’activité.", "Un repère de séance peut aider à lire le milieu.", "Utiliser un repère de séance comme support d’une question qui revient au retour. Un seul contraste suffit pour donner à voir un littoral mobile.", "Au départ, nous avons décrit ce secteur autour du repère. Qu’est-ce qu’on voit autrement maintenant ? Gardons une différence et cherchons ce qui peut l’expliquer."),
        ], questions: [
            q(0, "Vous utilisez déjà un amer pendant la navigation. Comment lui donner aussi un rôle dans un échange environnemental ?", ["Faire préciser au groupe le secteur autour de cet amer, puis comparer le rivage au retour.","Demander de mémoriser son nom et sa position sur la carte.","Faire choisir un autre amer pour compléter l’exercice de repérage."], 0, "Le repère devient un support commun pour décrire et comparer le milieu. Nommer des amers et travailler leur position sont des objectifs de voile valables, mais ne constituent pas ce prolongement environnemental. La compétence du moniteur fournit ici un point d’appui à la transmission."),
            q(1, "Le groupe veut comparer le niveau d’eau au départ et au retour. Quel échange rend votre choix de support compréhensible ?", ["Présenter la liste des repères fixes et mobiles visibles depuis la zone.","Demander à chacun de choisir son repère préféré avant de raconter la sortie.","Faire discuter quel support restera comparable quand l’eau changera de hauteur."], 2, "La question part du phénomène à observer et donne une raison au choix du repère. Une liste peut apporter du vocabulaire ; des préférences individuelles peuvent enrichir un récit. Elles ne garantissent pas un support adapté et partagé pour cette comparaison."),
            q(2, "Un banc visible au départ sera recouvert au retour. Quel fil d’échange peut accompagner la séance ?", ["Retenir son emplacement pour une séance de navigation ultérieure.","Faire une hypothèse sur le paysage du retour, puis la confronter au même secteur.","Présenter d’abord les horaires de tous les ports voisins."], 1, "Vérifier l’hypothèse au retour permet de comparer le même lieu à deux moments différents. Le groupe peut constater que son paysage évolue. Le repérage de navigation et les prévisions restent des outils professionnels, mais une présentation générale de ces outils ne remplace pas ce fil d’observation."),
            q(3, "Vous souhaitez discuter une différence du rivage à partir de photos. Quel support sert le mieux cet objectif ?", ["Deux points de vue spectaculaires pour susciter une réaction au paysage.","Deux cadrages différents pour montrer le maximum de détails du site.","Un point de vue répété avec repère fixe et conditions notées pour discuter les différences."], 2, "La comparaison appuyée sur un repère et un contexte connus permet de questionner ce qui a changé. Des images spectaculaires ou variées peuvent servir à d’autres échanges, mais leurs différences de cadrage compliquent ici l’interprétation du changement."),

            q(4, "Au retour, le groupe pense que la plage a rétréci. Comment utiliser un repère pour discuter cette impression ?", ["Comparer depuis un autre endroit qui montre davantage de plage.","Retrouver le même point de vue et situer le niveau de marée.","Comparer le rivage au bateau le plus proche de la plage."], 1, "Retrouver un point de vue stable et connaître le niveau de marée aide à distinguer recouvrement, cadrage et changement du rivage. Changer d’endroit introduit une nouvelle différence dans la comparaison. Un bateau mobile n’apporte pas la même référence fixe."),
        ],
    },
    {
        id: 'ciel-vent', titre: 'Observer le ciel et le vent', duree: "6 min", objectif: "Faire décrire des indices de vent et de ciel, puis distinguer ce qu’ils montrent de ce qu’on prévoit pour la séance.", actionsTerrain: [], ressources: [wiki.sens, wiki.climat, wiki.mer], sources: [brise],
        fiches: [
            f("Un même vent, des effets différents", "Drapeau et manche à air montrent l’écoulement de l’air à leur emplacement. Bâtiment, relief ou abri peuvent le modifier : deux drapeaux proches peuvent donc réagir différemment. Situez-les avant de les comparer. Votre lecture professionnelle du vent fournit le point de départ ; l’échange porte sur les effets du lieu dans les observations du groupe.", "Pendant la préparation, comparez deux drapeaux proches : « Sont-ils exposés de la même manière ? Qu’y a-t-il autour de chacun ? ». Faites repérer ce qui pourrait expliquer la différence entre les deux drapeaux, comme un bâtiment ou du relief.", "Un indice de vent se lit avec son exposition.", "Faire observer comment les bâtiments et le relief peuvent modifier le vent ressenti selon l’endroit où l’on se trouve.", "Ces deux indices ne réagissent pas de la même façon. Avant de dire que le vent change partout, regardons leurs emplacements : qu’est-ce qui peut modifier le passage de l’air ici ?"),
            f("Mettre des mots sur une variation vécue", "Un drapeau qui se tend puis retombe peut montrer une variation du vent. Il ne fournit pas une vitesse exacte. Décrire plusieurs instants est plus utile que retenir le mouvement le plus spectaculaire. Le ressenti peut compléter l’échange, sans remplacer une mesure. On peut faire observer une variation sans lui attribuer un chiffre ni l’étendre à toute la zone.", "À une pause, regardez un drapeau une minute : « Reste-t-il tendu de la même façon ? ». Distinguez la description d’un chiffre mesuré ou prévu.", "Observer une variation et mesurer une vitesse sont deux démarches.", "Aider le groupe à décrire une expérience du vent avec précision avant de lui attribuer un chiffre. Faire le lien entre sensation à bord et indice visible.", "Nous avons senti le vent forcir, puis faiblir. Regardons ce que fait le drapeau pendant une minute : reste-t-il tendu ou retombe-t-il par moments ? Il nous aide à voir ces variations, mais ne nous donne pas une vitesse précise."),
            f("Raconter une évolution du ciel", "Couverture nuageuse, mouvement des nuages et visibilité se décrivent sans connaître tous les noms. Suivez une évolution et confrontez-la aux prévisions locales. Un nuage sombre isolé ne prédit pas toute la séance ; un ciel bleu ne garantit pas des conditions constantes. Faites dire ce qui a réellement changé avant de proposer une explication de la suite.", "Au départ puis à une pause : « Le ciel est-il le même ? Qu’est-ce qui a changé ? ». Comparez la description aux prévisions du créneau.", "Décrire le ciel n’exige pas de reconnaître tous les nuages.", "Choisir des mots descriptifs accessibles plutôt que chercher immédiatement des noms de nuages. Préparer un retour sur une évolution réellement observée.", "Au départ, le ciel ressemblait à ceci. Qu’est-ce qui a changé dans la couverture ou la visibilité ? Comparons ce que nous observons aux prévisions, sans en déduire avec certitude le temps qu’il fera ensuite."),
            f("Faire expliquer un écart entre les indices", "Vent ressenti, vagues et ciel renseignent sur des phénomènes différents. Une houle peut venir de loin malgré un vent local faible ; un abri peut atténuer le ressenti. Assemblez ces indices sans les confondre, puis confrontez-les aux prévisions. Le choix d’organisation reste celui du moniteur dans son cadre habituel ; l’échange fait comprendre ce qui motive son interprétation.", "Faites compléter : « Ici, nous observons… ; pour la suite, il est annoncé… ». Expliquez un écart entre vent et vagues sans chercher un indice qui résumerait tout.", "Plusieurs indices se complètent, chacun avec ses limites.", "Utiliser une discordance vécue entre vent, vagues et ciel pour ouvrir une explication du milieu. Le groupe confronte les indices au lieu de retenir un signe unique.", "Nous sentons peu de vent, mais les vagues sont présentes. Ces indices parlent-ils exactement du même phénomène ? Une houle peut venir d’ailleurs : cherchons ce que chaque observation nous apprend."),
            f("Le bilan météo devient un récit de la sortie", "Le départ et le retour permettent de suivre un indice : régularité du drapeau, couverture nuageuse ou contraste entre vent et houle. Faites rappeler le constat initial, décrire celui du retour et retenir une différence. La sortie devient une occasion courte de parler d’un milieu qui évolue, tout en gardant l’organisation et la surveillance de l’activité sportive.", "Au briefing : « Gardons un indice à regarder au retour ». À terre, comparez les descriptions et formulez une idée sur l’évolution observée.", "Un indice suivi pendant la séance donne du sens à une notion de météo.", "Prolonger le retour sportif par une comparaison de deux observations. Faire retenir une évolution vécue plutôt qu’ajouter une leçon de météo.", "Quel indice avons-nous suivi depuis le départ ? Que montre-t-il maintenant ? Nous pouvons raconter une évolution du lieu à partir de ce que nous avons vraiment observé."),
        ], questions: [
            q(0, "Deux drapeaux proches réagissent différemment. Vous voulez faire comprendre le rôle du lieu dans ce qui est observé. Quelle question poser ?", ["Lequel décrit le mieux la direction qu’il faudrait mémoriser ?","Qu’est-ce qui diffère dans leur exposition et le passage de l’air autour d’eux ?","Quel chiffre du bulletin pouvons-nous associer à chacun ?"], 1, "Comparer l’exposition fait travailler l’effet du lieu à partir d’un contraste visible. Mémoriser une direction ou rechercher un chiffre poursuit d’autres objectifs. Ici, le moniteur aide à lire la scène plutôt qu’à choisir un indice comme réponse unique."),
            q(1, "Le groupe parle d’un vent « fort » au retour. Quelle consigne aide à préciser ce vécu sans faire un cours de mesure ?", ["Regardons le même indice pendant une minute : reste-t-il pareil ou varie-t-il ?","Retenons le moment le plus fort pour donner un chiffre à toute la sortie.","Comparons les chiffres de plusieurs bulletins avant de décrire notre observation."], 0, "La consigne invite à décrire une variation avec un support commun. Elle enrichit les mots du groupe sans prétendre mesurer une vitesse exacte. Un maximum ne résume pas la séance ; la comparaison documentaire peut compléter l’analyse du moniteur, sans remplacer le récit de ce qui a été vécu."),
            q(2, "Vous voulez utiliser une évolution du ciel pour un échange court. Quelle entrée permet de participer sans connaître les noms des nuages ?", ["Faire choisir un nom de nuage dans une liste puis expliquer ses caractéristiques.","Présenter les symboles du bulletin avant de regarder ce qui a changé.","Faire comparer couverture et visibilité au départ et au retour avec des mots descriptifs."], 2, "Des descriptions accessibles permettent de participer et de suivre une évolution réelle. Une classification ou les symboles météo peuvent répondre à un autre besoin. Ils ne sont pas un préalable à cet échange sur un changement observé pendant la séance."),
            q(3, "Le groupe s’étonne de voir des vagues malgré un vent ressenti faible. Quel angle développe sa compréhension du milieu ?", ["Faire expliquer pourquoi chaque indice ne parle pas du même phénomène, avec la houle comme exemple.","Reprendre les réglages adaptés aux vagues pour consolider l’objectif sportif.","Présenter la prévision de demain pour comparer les conditions de navigation."], 0, "La question sur les indices ouvre une explication du lieu : vent ressenti et houle peuvent avoir des origines différentes. Réglages et prévisions sont utiles à la navigation ; l’apport COP’UN est ici de relier le contraste vécu à une compréhension environnementale."),

            q(4, "Vous voulez que le groupe remarque l’évolution du vent pendant la sortie. Quelle consigne rend la comparaison utile ?", ["Retenir le vent le plus fort ressenti pour résumer toute la séance.","Nommer les nuages au départ pour en déduire le vent du retour.","Décrire un même indice exposé au départ et au retour."], 2, "Un même indice, situé dans son exposition, donne une base de comparaison entre deux moments. Un maximum ressenti ne décrit pas toute l’évolution et peut dépendre de l’emplacement. Nommer un nuage ne permet pas de déduire à lui seul le vent du retour. L’objectif est de faire décrire un changement vécu."),
        ],
    },
    {
        id: 'traces-vivant', titre: 'Repérer le vivant et ses traces', duree: "7 min", objectif: "Lire des indices de vie, les relier au milieu et conduire une courte observation avec le groupe pendant la séance nautique.", actionsTerrain: [], ressources: [wiki.vivant, wiki.algues, wiki.gestes, wiki.sens],
        sources: [{ titre: 'Milieux marins et littoraux — Office français de la biodiversité', href: 'https://ofb.gouv.fr/les-milieux-marins-et-littoraux' }],
        fiches: [
            f("Faire remarquer ce qui ne bouge pas", "Chercher le vivant ne revient pas seulement à attendre un mouvement. Moules fixées, algues sur leur support et plantes du haut de plage sont aussi observables. Mare, roche humide et sable découvert offrent des conditions différentes : eau, support, exposition. Orientez le regard vers ces différences sans déplacer ni arracher. Une coquille vide est un reste, pas une preuve de présence actuelle.", "Depuis l’accès prévu : « Qu’est-ce qui se déplace, reste fixé ou est une trace ? Qu’aurions-nous manqué en ne cherchant que le mouvement ? ».", "Le mouvement n’est pas le critère du vivant.", "Élargir une recherche spontanée d’animaux mobiles avec un critère d’observation, sans engager un inventaire d’espèces.", "Si nous regardons seulement ce qui bouge, qu’allons-nous manquer ? Cherchons aussi ce qui reste fixé, puis distinguons le vivant et les traces laissées dans ce lieu."),
            f("Faire raisonner à partir d’une trace", "Des empreintes montrent un passage et parfois son trajet, pas forcément son heure ou son auteur. Une coquille ou une plume peuvent avoir été transportées ; un trou ne confirme pas son occupant. Distinguez description, hypothèse et vérification : « Des empreintes traversent le sable » est un fait ; « un oiseau cherchait sa nourriture » demande d’autres indices.", "Sans toucher la trace, faites compléter : « Je vois… ; cela pourrait indiquer… ; pour vérifier, il faudrait… ». Gardez le nom incertain comme une piste.", "Une trace permet un raisonnement, pas une histoire certaine.", "Séparer fait et hypothèse dans les échanges du groupe. Le moniteur n’a pas besoin de fournir immédiatement le nom de l’auteur pour faire travailler l’observation.", "Nous voyons des empreintes qui passent ici. Quelle histoire pourrait les expliquer ? Et quels indices avons-nous réellement pour la soutenir ? Gardons ce qui est sûr et ce qui reste à vérifier."),
            f("Un comportement raconte un besoin", "Un oiseau qui picore ou sonde le sable renseigne sur une recherche de nourriture ; un groupe au repos montre un autre usage. Reliez activité et emplacement : la marée peut découvrir puis recouvrir une zone d’alimentation. Cela explique un besoin du vivant sans identifier chaque espèce. La seule présence d’un animal ne prouve pas qu’il niche ici.", "À distance : « Que font-ils ? Que permet cet endroit ? ». Si leur activité s’interrompt à votre arrivée, écartez le groupe et poursuivez l’échange ailleurs.", "Le comportement aide à comprendre l’utilité du lieu.", "Passer de la question « quel animal ? » à « que fait-il ici ? ». Relier une scène observable au rôle du lieu pour le vivant.", "Avant de chercher leur nom, regardons ce que ces oiseaux font. S’ils se nourrissent ici, qu’est-ce que cet endroit leur permet ? Le littoral est aussi leur espace de vie."),
            f("Répondre à « aujourd’hui, il n’y a rien »", "Ne rien repérer ne signifie pas absence de vivant : certains organismes sont cachés et d’autres utilisent le secteur à un autre moment. Marée, saison, météo et durée de regard changent ce qui est visible. Comparez depuis le même accès, pendant un temps semblable et avec les conditions notées. Deux observations ne suffisent pas à conclure à une baisse du vivant.", "Si le groupe dit « il y en avait plus hier », précisez quoi, où, marée et durée. Reprenez une observation comparable avant de chercher une cause.", "Une différence de visibilité n’est pas une preuve de diminution.", "Reformuler une absence de rencontre sans nier le ressenti du groupe. Donner les clés de contexte utiles pour comparer deux sorties.", "Nous n’avons rien repéré pendant cet arrêt. Est-ce la même chose que dire qu’il n’y a rien ? Comparons le moment, la marée et notre temps de regard avec la dernière sortie."),
            f("Une question qui donne prise au regard", "« Regardez la nature » laisse le groupe sans entrée précise. Choisissez un détail commun : trace, forme fixée ou comportement. Posez une question, laissez regarder et confrontez deux descriptions. Reprenez les faits avant l’explication. Si le nom manque, décrivez forme, support ou activité et vérifiez plus tard. La qualité de l’échange ne dépend pas d’une liste d’espèces.", "À une pause prévue, faites regarder un même indice trente secondes. Demandez ce qui soutient chaque hypothèse et retenez ensemble une idée.", "Une question précise transforme un détail en observation partagée.", "Remplacer l’invitation générale par une observation courte et partagée. La question permet de transmettre même lorsque l’identification reste incertaine.", "Regardez tous cette trace pendant quelques instants. Décrivez une chose que vous voyez vraiment. Qu’est-ce qui soutient votre explication, et qu’est-ce qui reste une hypothèse ?"),
            f("Garder une occasion, pas une rencontre imposée", "Une attente, une pause à terre ou le retour peuvent offrir une minute d’observation. Choisissez un détail visible depuis une position qui vous permet de continuer à encadrer et à surveiller le groupe. Si l’animal attendu manque, utilisez une trace ou un organisme fixé plutôt que de partir à sa recherche. Reliez l’indice au lieu, puis reprenez l’activité sportive.", "Préparez un point possible et une solution de remplacement. À la pause : une question, un regard partagé, une idée à retenir. Au retour : « Qu’avez-vous regardé autrement ? ».", "Le moniteur fait découvrir un lien avec le milieu dans sa séance.", "Préparer un sujet de remplacement qui conserve l’objectif d’observation quand l’animal attendu n’est pas visible. L’échange reste dans le temps de la séance.", "Nous n’avons pas vu l’animal attendu, mais ces traces nous racontent un passage. Que pouvons-nous en comprendre depuis notre position, avant de reprendre l’activité ?"),
        ], questions: [
            q(0, 'Le groupe observe des animaux dans une mare, puis dit que le rocher voisin est « sans vie » car rien n’y bouge. Comment élargir son regard ?', ['Attendre un déplacement pour vérifier si le rocher accueille du vivant.', 'Chercher aussi les organismes fixés et distinguer les coquilles vides.', 'Compter les coquilles visibles pour comparer le vivant des deux endroits.'], 1, 'Le vivant peut être fixé à un support et ne pas présenter de mouvement visible. Des algues attachées ou des moules fixées orientent le regard vers d’autres formes de vie. Les coquilles vides sont des restes : les compter ne donne pas le nombre d’animaux présents. La mare et le rocher offrent aussi des conditions différentes à faire observer.'),
            q(1, 'Des empreintes traversent le sable humide jusqu’à la laisse de mer. Un stagiaire affirme : « Un oiseau vient de manger ici. » Que lui faire préciser ?', ['La forme des empreintes pour déduire l’heure du passage et le repas.', 'Le nom de l’oiseau pour confirmer son alimentation sur cette plage.', 'Ce que montre la trace et les indices manquants pour parler d’un repas.'], 2, 'La trace montre un passage et un trajet, mais pas à elle seule son heure ni une prise de nourriture. La forme peut aider une identification ; un nom ne confirme pas l’activité de cet individu. Faites distinguer le fait observé de l’hypothèse, puis chercher ce qui permettrait de l’appuyer sans modifier la trace.'),
            q(2, 'Des oiseaux sondent le sable découvert près de l’eau. Sans les identifier, quel lien pouvez-vous faire construire au groupe ?', ['Ce comportement indique une recherche de nourriture sur une zone découverte.', 'Leur présence indique que cette zone est aussi leur lieu de reproduction.', 'Leur regroupement indique que cette zone sert surtout d’abri contre le vent.'], 0, 'Le comportement observé permet de parler d’une recherche de nourriture et de la zone rendue accessible par la marée. Il ne démontre ni la reproduction ni un rôle principal d’abri contre le vent. Le moniteur peut relier une activité à un lieu avant de chercher le nom de l’espèce.'),
            q(3, 'Hier, le groupe a vu plusieurs oiseaux pendant dix minutes à marée basse ; aujourd’hui, aucun pendant une minute à marée haute. Quelle suite donner à la comparaison ?', ['Chercher quel changement du site a fait diminuer le nombre d’oiseaux.', 'Reprendre des observations comparables et noter leurs conditions.', 'Attribuer cette différence au déplacement saisonnier des oiseaux.'], 1, 'La durée et la marée diffèrent : la visibilité et l’usage du secteur peuvent donc changer. On ne dispose pas encore d’une comparaison permettant de conclure à une diminution ou à un déplacement saisonnier. Revenir au même point avec un temps d’observation semblable et noter les conditions permet de mieux discuter la différence ; cela ne constitue pas un suivi complet de la population.'),
            q(4, 'Pendant une pause, vous repérez une trace dont vous ne connaissez pas l’auteur. Quelle consigne fait réellement travailler l’observation ?', ['Donner le nom le plus probable, puis demander au groupe de le retenir.', 'Laisser chacun chercher un animal différent, puis comparer les noms trouvés.', 'Faire décrire la trace, puis demander quels indices soutiennent une hypothèse.'], 2, 'Une description partagée donne une base au raisonnement : forme, disposition et lieu. On peut confronter des hypothèses en demandant sur quels indices elles reposent, puis vérifier l’identification plus tard. Proposer un nom à mémoriser ou disperser la recherche vers plusieurs animaux ne remplit pas ce même objectif d’observation d’un indice commun.'),
            q(5, 'Vous aviez prévu une observation d’oiseaux pendant une pause à terre. Ils ne sont pas visibles, mais des traces le sont depuis l’accès prévu. Quelle adaptation choisir ?', ['Utiliser les traces pour un court échange, puis reprendre la séance.', 'Rejoindre un autre secteur pour retrouver l’observation prévue.', 'Remplacer l’observation par la présentation des oiseaux attendus.'], 0, 'L’occasion pédagogique peut s’appuyer sur ce qui est réellement visible : décrire une trace, proposer une hypothèse et retenir un lien avec le lieu. Changer de secteur suppose de revoir l’organisation de la séance ; ce n’est pas nécessaire pour maintenir cet échange. Une présentation des oiseaux peut informer, mais elle ne remplace pas le travail d’observation proposé ici.'),
        ],
    },
    {
        id: 'sans-deranger', titre: 'Approcher sans déranger', duree: "6 min", objectif: "Repérer un changement de comportement et adapter la séance pour faire observer le vivant en préservant son activité.", actionsTerrain: [], ressources: [wiki.gestes, wiki.impact],
        fiches: [
            f("Faire voir le dérangement avant la fuite", "Un animal peut arrêter de se nourrir ou surveiller notre présence avant de fuir. L’absence d’envol ne garantit donc pas une observation sans effet. Regardez son activité à distance puis son éventuel changement à l’arrivée du groupe. Ce signal sert à adapter notre présence, pas à tester une limite d’approche. Le littoral répond aussi à ses besoins de repos et d’alimentation.", "Si l’activité s’interrompt à votre arrivée, écartez le groupe et expliquez : « Notre présence a changé ce qu’ils faisaient ». Poursuivez depuis une autre position.", "Un changement d’activité compte avant la fuite.", "Donner une raison observable à votre adaptation de position. Le groupe apprend à lire son effet sur une activité animale, sans tester une limite d’approche.", "Ils se nourrissaient ; maintenant ils nous surveillent. Même sans envol, leur activité a changé. Écartons-nous : laissons-les reprendre leur alimentation."),
            f("Dépasser « nous ne restons qu’une minute »", "Fuir demande de l’énergie ; interrompre l’alimentation ou le repos retire du temps à ces activités. Un passage bref peut s’ajouter à ceux des autres groupes. L’enjeu ne se limite donc pas à la durée de notre arrêt. Faire comprendre le besoin interrompu suffit, sans demander au groupe de connaître les dépenses d’énergie de chaque espèce.", "Si un stagiaire dit « nous ne restons qu’une minute », posez : « Et si plusieurs groupes font de même ? ». Reliez la répétition au temps laissé à l’animal.", "Des interruptions brèves peuvent se cumuler.", "Faire raisonner sur la répétition des passages, avec une explication du besoin interrompu plutôt qu’une culpabilisation du groupe.", "Notre arrêt est bref. Mais si chaque groupe interrompt leur repos, quel temps leur reste-t-il ? Pensons aussi à ceux qui sont passés avant nous et à ceux qui viendront après."),
            f("Expliquer le changement de trajectoire", "Si le comportement change pendant l’approche, arrêtez celle-ci et écartez-vous en laissant un passage libre. Silence ou petit effectif ne garantissent pas l’absence de gêne. L’explication peut se poursuivre depuis un autre point. Choisissez trajet et arrêt avec les consignes du site ; une distance fixe unique ne convient pas à tous les animaux et à toutes les situations.", "Préparez un arrêt de remplacement. Si l’animal devient vigilant, modifiez le trajet et expliquez ce choix, sans l’encercler ni bloquer son passage.", "Notre position s’adapte au comportement et aux consignes du lieu.", "Associer votre choix de déplacement à un signe repéré et à un besoin du vivant. L’adaptation devient une démonstration de pratique attentive au milieu.", "Nous changeons de place parce que leur comportement a changé. Laissons-leur un passage et poursuivons notre échange plus loin : nous pouvons comprendre cette scène sans rester tout près."),
            f("Donner du sens à un contour sans animal visible", "Un reposoir peut être vide entre deux utilisations et un nid difficile à voir. Une zone balisée reste à respecter même sans animal visible. Les animaux peuvent utiliser ce lieu différemment selon la marée et la saison. Pour expliquer pourquoi vous contournez une zone, utilisez les indications locales plutôt que de promettre une rencontre ou de supposer une raison identique à tous les balisages.", "Avant la sortie, repérez les secteurs signalés. Si le groupe demande pourquoi contourner, expliquez le besoin indiqué et la limite de ce que l’on voit aujourd’hui.", "Un lieu sensible se respecte même lorsqu’il paraît vide.", "Répondre à une incompréhension du balisage en distinguant notre aperçu du site et les usages du vivant à d’autres moments.", "Nous ne voyons pas d’animal maintenant. Cela ne signifie pas que cet endroit ne sert pas. Les indications du site nous aident à respecter des besoins que notre seul passage ne montre pas."),
            f("Un geste de séance devient une idée à retenir", "S’écarter peut devenir une occasion d’apprentissage. Nommez l’activité interrompue, expliquez le changement de trajectoire et faites retenir ce que cela cherche à préserver. Vous montrez comment la pratique sportive tient compte du vivant. Cet échange reste court, sans identification obligatoire ni nouvelle approche pour refaire la démonstration.", "Depuis la position de retrait : « Quel signe nous a fait changer de place ? Qu’est-ce que cela laisse à l’animal ? ». Retenez une idée puis reprenez la séance.", "Un choix de trajet peut faire comprendre un geste de protection.", "Revenir brièvement sur votre adaptation pour que le groupe comprenne son effet, sans répéter l’approche ni prolonger l’observation.", "Quel signe nous a fait reculer ? Quelle activité l’animal pourra-t-il reprendre si nous nous éloignons ? Gardons cette idée pour la suite de notre séance."),
        ], questions: [
            q(0, 'Des oiseaux restent sur place, mais arrêtent de se nourrir quand le groupe approche. Quel signe retenir pour adapter la séance ?', ['L’absence d’envol indique qu’ils tolèrent cette distance.', 'Leur immobilité permet de prolonger l’arrêt du groupe.', 'L’interruption de l’alimentation peut déjà signaler un dérangement.'], 2, 'Le dérangement ne se limite pas à la fuite. Interrompre l’alimentation pour surveiller une présence peut déjà avoir un coût pour l’animal. Le maintien sur place ne suffit donc pas à conclure que notre distance convient.'),
            q(1, 'Chaque groupe reste peu de temps près d’un reposoir, mais les passages se succèdent. Que faire comprendre aux moniteurs ?', ['Les effets peuvent s’additionner en interrompant le repos.', 'La brièveté de chaque arrêt limite l’enjeu à chaque groupe.', 'L’absence de contact limite l’enjeu à la distance d’approche.'], 0, 'Plusieurs interruptions brèves peuvent réduire le temps de repos ou d’alimentation. Il faut donc considérer la succession des passages, pas seulement la durée de notre arrêt. Le dérangement peut exister sans contact physique avec l’animal.'),
            q(2, 'Un animal devient vigilant pendant votre approche. Quelle adaptation répond le mieux à ce signal ?', ['Arrêter le groupe sur place pour terminer l’explication.', 'S’écarter par un trajet qui lui laisse un passage libre.', 'Réduire le groupe à quelques personnes pour poursuivre.'], 1, 'S’écarter réduit la pression et laisser un passage évite d’enfermer l’animal dans notre présence. Un groupe plus petit ou immobile peut encore interrompre son activité. On adapte le trajet à son comportement plutôt que de maintenir l’approche sous une autre forme.'),
            q(3, 'Un stagiaire demande pourquoi contourner une zone balisée où aucun animal n’est visible. Quelle explication lui donner ?', ['L’absence d’animaux visibles permet d’y faire un passage bref.', 'La protection concerne surtout les moments où les oiseaux nichent.', 'Le site peut protéger un lieu sensible même quand il paraît vide.'], 2, 'Un nid peut être discret et un reposoir occupé à d’autres moments. Le balisage ne dépend pas de ce que notre groupe voit aujourd’hui et protège des besoins qui varient avec la marée ou la saison. On suit les consignes du site sans décider qu’un passage est acceptable à partir de cette seule observation.'),

            q(4, "Vous avez éloigné le groupe car des oiseaux ont arrêté de se nourrir. Quel retour transforme cette adaptation en apprentissage ?", ["Expliquer le signe observé et ce que le recul cherche à leur permettre.","Donner la distance atteinte comme une règle pour toutes les espèces.","Revenir brièvement à la première position pour faire constater le changement."], 0, "Relier le comportement observé et notre adaptation fait comprendre le besoin préservé. La distance n’est pas une règle universelle indépendante du site et des animaux. Répéter l’approche pour la démonstration risque de renouveler l’interruption ; l’explication peut se faire depuis la position de retrait."),
        ],
    },
    {
        id: 'plages-dunes', titre: 'Préserver plages et dunes', duree: "6 min", objectif: "Relier les déplacements du sable, le rôle des plantes et nos choix de passage à la préservation du lieu de pratique.", actionsTerrain: [], ressources: [wiki.dunes, wiki.gestes, wiki.impact],
        fiches: [
            f("Relier le vent de la séance au sable", "L’eau transporte des matériaux sur la plage ; le vent peut déplacer le sable sec vers le haut de plage. Un obstacle ralentit ce transport et peut favoriser une accumulation. Plage et dune appartiennent ainsi à un milieu mobile. Une touffe entourée de sable donne une entrée pour relier le vent de la séance à la forme du littoral.", "Depuis le chemin : « Qu’est-ce qui transporte ce sable ? Qu’est-ce qui le ralentit ici ? ». Appuyez la réponse sur les indices visibles.", "Vent et eau participent aux mouvements du sable.", "Partir d’un phénomène vécu en navigation pour lire un détail du paysage. Le groupe comprend un lien entre plage et dune sans entrer dans la végétation.", "Ce vent nous accompagne sur l’eau ; ici, il déplace aussi le sable. Regardez l’accumulation autour de cet obstacle : qu’est-ce qui transporte le sable, et qu’est-ce qui le ralentit ?"),
            f("Les plantes font partie du fonctionnement du lieu", "La végétation ralentit le vent près du sol et ses racines contribuent au maintien du sable. Elle participe au fonctionnement de la dune. La piétiner ou l’arracher peut fragiliser ce rôle. Ce lien suffit pour donner du sens à sa préservation, sans reconnaître chaque plante ni promettre que la végétation empêche tout changement.", "Depuis l’accès prévu : « Si ces plantes sont abîmées, qu’est-ce qui change pour le sable ? ». Reliez la réponse au choix du passage.", "Préserver les plantes aide à préserver le fonctionnement de la dune.", "Présenter une fonction de la végétation plutôt qu’une liste de plantes à protéger. Cette explication donne une raison au choix de passage.", "Ces plantes ne sont pas seulement posées sur la dune : elles contribuent à retenir le sable. Si elles sont abîmées, qu’est-ce qui peut changer autour d’elles ?"),
            f("Notre passage s’ajoute aux autres", "Un raccourci peut sembler sans effet pour un groupe qui passe une seule fois. Mais les passages se répètent : les plantes se dégradent et du sable nu peut apparaître. Chemins et passerelles canalisent le piétinement sur les accès prévus. Le transport du matériel compte aussi. Expliquez ce que l’itinéraire préserve plutôt que de donner seulement une consigne.", "Avant le déplacement : « Que se passe-t-il si chaque groupe prend ce raccourci ? ». Faites repérer l’accès prévu pour le groupe et le matériel.", "Notre passage s’ajoute à ceux des autres.", "Traiter l’argument du passage unique avec l’effet cumulé des usages. Le trajet devient compréhensible au-delà de l’obéissance à une consigne.", "Nous ne passons qu’une fois, mais nous ne sommes pas les seuls. Que deviendrait ce raccourci si chaque groupe faisait le même choix ? En suivant le chemin, nous évitons de piétiner la végétation autour."),
            f("Une plage nette n’est pas le seul objectif", "Des algues échouées peuvent nourrir et abriter du vivant ou contribuer à la vie du haut de plage. Les retirer avec les déchets humains n’a pas le même effet qu’une collecte ciblée. Une plage plus nette n’est donc pas forcément mieux préservée. Vérifiez les consignes locales et les conditions de manipulation : préservez le naturel et signalez les objets dangereux au responsable.", "Distinguez un déchet identifiable et un dépôt naturel : « Que cherche-t-on à retirer ? Que laisse-t-on au milieu ? ». Suivez les consignes du site.", "Le rôle des éléments compte davantage que l’aspect final.", "Faire discuter l’effet d’un geste sur le milieu à partir des rôles différents d’un dépôt naturel et d’un déchet.", "Un emballage et des algues échouées peuvent être côte à côte sans avoir le même rôle. Si l’on retire tout pour faire net, qu’est-ce qu’on enlève aussi au vivant ?"),
            f("Une minute d’explication sur le chemin vers l’eau", "Le chemin vers l’eau fait déjà partie de la séance. Une touffe, une passerelle ou un raccourci marqué permettent d’expliquer le trajet retenu. Posez une question sur son rôle et reliez la réponse à notre passage. Une minute peut suffire pour donner du sens environnemental à une organisation sportive que vous conduisez déjà.", "Avant de rejoindre l’eau : « Que préserve ce chemin ? ». Faites retenir le lien entre plantes, sable et passages, puis poursuivez l’installation.", "Un trajet préparé peut accueillir une explication sur le milieu.", "Utiliser le déplacement déjà prévu dans la séance pour transmettre un lien entre plantes, sable et passages, sans ajouter une visite du site.", "Pourquoi prenons-nous ce chemin ? Regardons ce qu’il permet de laisser en place autour de nous. Notre trajet vers l’eau fait déjà partie de notre manière de prendre soin du lieu."),
        ], questions: [
            q(0, 'Pendant un épisode de vent, le groupe voit du sable sec s’accumuler derrière les touffes, hors de portée des vagues. Quel lien expliquer ?', ['Les vagues déposent le sable derrière les touffes au fil de la marée.', 'Le vent transporte le sable et les touffes ralentissent son déplacement.', 'Le sable descend de la dune et les touffes freinent ce glissement.'], 1, 'Le vent peut transporter du sable sec de la plage vers le haut de plage. Les touffes ralentissent ce transport et favorisent une accumulation. Ici, les indices permettent de montrer ce mouvement : il ne s’agit ni d’un dépôt direct des vagues ni d’un glissement depuis la dune.'),
            q(1, 'Une stagiaire voit la végétation de la dune comme un simple couvert sur le sable. Quel rôle lui faire comprendre ?', ['Elle ralentit le vent près du sol et contribue à retenir le sable.', 'Elle protège le sable surtout en limitant son exposition au soleil.', 'Elle recouvre le sable après que la dune a fini de se former.'], 0, 'La végétation intervient dans le fonctionnement de la dune : elle ralentit le vent et ses racines contribuent au maintien du sable. Elle n’est donc pas seulement un couvert installé après sa formation. La piétiner peut fragiliser ce rôle.'),
            q(2, 'Le groupe propose un raccourci dans la dune : « Nous ne passons qu’une fois. » Quel argument expliquer ?', ['Le chemin aménagé sert surtout à faciliter le déplacement du matériel.', 'Espacer les marcheurs dans la végétation suffit à limiter le piétinement.', 'Les passages répétés au même endroit peuvent dégrader la végétation.'], 2, 'Notre passage s’ajoute à ceux des autres groupes. Un raccourci répété peut dégrader les plantes et ouvrir une zone de sable nu. Les accès aménagés canalisent le piétinement ; disperser les marcheurs dans la végétation ne remplit pas ce rôle.'),
            q(3, 'Vous préparez une collecte autorisée près de la dune. Quel critère doit guider les gestes du groupe ?', ['Retirer les éléments qui se détachent facilement du sable.', 'Distinguer les déchets manipulables des éléments naturels à préserver.', 'Retirer les éléments secs et laisser ceux qui sont encore humides.'], 1, 'L’origine et la nature des éléments comptent, avec les consignes du site et les conditions de manipulation. Des algues sèches restent naturelles et utiles ; un objet facile à saisir n’est pas forcément à retirer. La végétation et les dépôts naturels restent en place.'),

            q(4, "Le groupe trouve le détour par la passerelle inutile. Quelle intervention relie ce trajet à l’environnement ?", ["Insister sur le confort du passage pour transporter le matériel.","Faire observer la végétation et expliquer l’effet des raccourcis répétés.","Faire apprendre les noms des plantes avant de choisir le passage."], 1, "L’effet du piétinement sur une végétation qui participe au maintien du sable donne du sens au trajet. Le confort peut être un avantage du passage, mais n’explique pas cet enjeu du milieu. Identifier les plantes n’est pas nécessaire pour comprendre le rôle de la végétation et suivre l’accès prévu."),
        ],
    },
    PARCOURS_LAISSE_DE_MER,
    {
        id: 'connaitre-site', titre: 'Participer à la connaissance du site', duree: "6 min", objectif: "Garder et partager une observation utile de la séance, avec son contexte et ses limites, sans demander une expertise naturaliste.", actionsTerrain: [], ressources: [wiki.partager, wiki.photos],
        fiches: [
            f("Faire formuler un fait partageable", "Une présence animale, une trace ou un changement vu pendant la séance peut intéresser les personnes qui suivent le site. Rapportez le fait et ses limites, sans produire un inventaire. « Trois oiseaux au repos à cet accès » est plus précis que « beaucoup de nature ». Vérifiez les consignes du destinataire pour savoir ce qu’il peut recueillir.", "Au retour : « Qu’avons-nous vraiment vu ? Qu’est-ce qu’on suppose ? ». Gardez un fait que le groupe peut décrire et situer.", "Une observation utile n’exige pas une liste d’espèces.", "Transformer le récit de sortie en observation précise, sans demander au groupe une identification complète ni un inventaire.", "Si nous racontons cette rencontre à quelqu’un qui n’était pas là, qu’est-ce que nous pouvons affirmer ? Commençons par ce que nous avons vu, puis distinguons nos suppositions."),
            f("Le contexte rend le récit utile", "Lieu assez précis, date et description donnent une base. Heure, nombre, marée ou activité peuvent compléter le contexte lorsqu’ils sont connus. « Ce matin » perd son sens plus tard : indiquez la date dans le message. Distinguez comptage et estimation, sans inventer les informations manquantes. Le destinataire doit pouvoir comprendre ce qui a été réellement observé.", "Formulez : « Trois oiseaux au repos, cale nord, le [date] à 9 h ». Précisez si le nombre est estimé ou si une information manque.", "Le contexte rend l’observation compréhensible pour quelqu’un d’absent.", "Faire préciser quelques éléments que le groupe connaît déjà de sa séance. La fiabilité vient du contexte et du doute explicite, pas du vocabulaire spécialisé.", "Où étions-nous, à quelle date et à quel moment ? Avons-nous compté ou estimé ? Une personne absente doit pouvoir situer notre observation sans que nous inventions les détails manquants."),
            f("Une image n’autorise pas un rapprochement", "Une photo depuis votre position peut aider à vérifier. Elle ne justifie pas de poursuivre un animal, déplacer un organisme ou entrer dans une zone fermée. Une image moins précise reste parfois utile avec une description située. Indiquez le doute sur le nom : la fiabilité tient au contexte et aux limites explicites, pas seulement au gros plan.", "Gardez une image depuis l’accès prévu : « Que permet-elle de confirmer ? Que laisse-t-elle incertain ? ». Renoncez au rapprochement si le comportement change.", "Documenter ne doit pas augmenter notre effet sur le vivant.", "Expliquer pourquoi vous renoncez au gros plan tout en conservant une documentation utile. Relier fiabilité de l’information et respect de la scène observée.", "Cette photo montre une partie de notre observation. Pour mieux comprendre, nous pouvons ajouter le lieu et une description. Nous n’avons pas besoin de nous rapprocher si cela change l’activité de l’animal."),
            f("Expliquer à qui l’observation peut servir", "Gestionnaire, association ou programme participatif recueillent des informations selon leurs thèmes et leurs formats. Vérifiez le canal avec le référent de la base. Une observation ordinaire et un problème à signaler rapidement ne se transmettent pas forcément de la même façon. Donnez faits, contexte et degré de certitude ; les consignes du destinataire orientent le partage.", "Avec le référent, préparez le canal adapté. Avant l’envoi : « Peut-on retrouver le lieu ? Le moment est-il clair ? Le doute est-il indiqué ? ».", "Destinataire adapté et doute explicite rendent le partage utile.", "Donner une destination concrète à la curiosité du groupe, avec le canal connu de la base. Ne pas transformer toute rencontre en signalement.", "Cette observation pourrait intéresser les personnes qui suivent le site. Vérifions ce qu’elles recueillent et comment. Nous transmettrons ce que nous avons vu, avec les limites de notre identification."),
            f("Une place dans le bilan sportif", "Une minute au bilan peut accueillir un fait, son lieu et son moment. Faites reformuler ce que le groupe a vu et à qui cela pourrait servir. Partagez si c’est pertinent avec le canal prévu ; sinon, gardez cette observation dans le retour de séance. Ce n’est ni une obligation de collecte de données ni un examen d’identification.", "Au rangement : « Quelle observation saurions-nous raconter précisément à quelqu’un qui n’était pas là ? ». Vérifiez contexte et incertitudes avant un partage éventuel.", "Le bilan sportif peut aussi garder une observation du milieu.", "Ajouter au retour de séance un fait du milieu et son intérêt éventuel. Le partage reste une possibilité pertinente, pas une obligation de collecte de données.", "Quelle observation d’aujourd’hui saurions-nous raconter précisément ? Que nous a-t-elle fait comprendre de notre lieu de pratique ? Voyons ensuite s’il est utile de la partager."),
        ], questions: [
            q(0, 'Vous avez une observation précise, sans liste complète des espèces du secteur. Comment envisager sa transmission ?', ['Compléter l’inventaire du secteur avant d’envoyer l’observation.', 'Attendre une seconde sortie pour produire un bilan du vivant.', 'Transmettre le fait observé en suivant les consignes du destinataire.'], 2, 'Une observation située peut être utile sans inventaire ni bilan complet du site. Sa valeur tient à ce qui a réellement été vu et à la précision des informations. Les consignes du destinataire permettent de savoir ce qu’il peut recueillir et sous quelle forme.'),
            q(1, 'Vous préparez un message à partir d’une observation d’oiseaux. Quelle formulation offre la base la plus exploitable ?', ['Trois oiseaux au repos, cale nord, ce matin à 9 h.', 'Trois oiseaux d’une espèce à confirmer, au bord de la mer.', 'Des oiseaux au repos sur le littoral, pendant notre séance.'], 0, 'Le lieu assez précis, le moment et la description permettent de situer l’observation. Les deux autres formulations apportent un renseignement, mais laissent le lieu ou le moment trop vagues. Le nom de l’espèce n’est pas indispensable pour donner cette base.'),
            q(2, 'Pour obtenir une photo plus précise, il faudrait s’approcher d’un animal qui surveille déjà le groupe. Quel choix retenir ?', ['Faire la photo rapidement en limitant le temps d’approche.', 'Garder la distance et documenter ce qui est visible de là.', 'Faire approcher une personne discrète plutôt que tout le groupe.'], 1, 'La documentation ne justifie pas d’augmenter le dérangement. Une approche brève ou menée par une seule personne peut encore interrompre l’activité de l’animal. On peut transmettre une photo moins précise et une description, en indiquant les limites de l’observation.'),
            q(3, 'Une photo évoque une espèce, mais vous n’êtes pas sûr. Comment rédiger le signalement ?', ['Indiquer cette espèce, car la photo permettra au destinataire de corriger.', 'Attendre de connaître le nom pour rédiger une description du passage.', 'Décrire les faits et présenter l’identification comme une hypothèse.'], 2, 'Un doute explicite permet au destinataire de distinguer observation et identification à vérifier. Donner le nom sans réserve transforme l’hypothèse en certitude. Il n’est pas nécessaire d’attendre ce nom pour transmettre une description utile, selon les consignes du destinataire.'),

            q(4, "Au bilan de séance, le groupe veut partager une rencontre avec un animal non identifié. Quelle préparation rend ce partage utile ?", ["Choisir le nom proposé par le plus grand nombre pour compléter le message.","Décrire le fait, situer lieu et date, puis vérifier le canal et préciser le doute.","Envoyer la photo seule pour laisser au destinataire tout le travail de contexte."], 1, "Le groupe peut contribuer avec une description située et un doute explicite, selon les consignes du canal choisi. Un vote ne confirme pas une identification. Une photo ne fournit pas à elle seule toutes les informations de lieu et de moment ; les ajouter permet de mieux comprendre l’observation."),
        ],
    },
];
export type ParcoursId = ParcoursFormation['id'];
